async function resolveFindAIIdentity(opinions, evidence, env) {
  const list=(Array.isArray(opinions)?opinions:[opinions]).filter(x=>x&&typeof x==='object');
  let fallback={kind:'product',brand:'',productLine:'',model:'',variant:'',category:'',size:'',visibleText:[],canonicalQuery:'',queryVariants:[],requiredTerms:[],negativeTerms:[],confidence:null};
  for(const opinion of list){
    const candidate=enrichFindAIIdentity(fallbackFindAIIdentity(opinion,evidence),evidence);
    if(findAIIdentityQuality(candidate,evidence).score>findAIIdentityQuality(fallback,evidence).score)fallback=candidate;
  }
  fallback=sanitiseFindAIIdentity(fallback,evidence);
  if(!env||!env.AI)return fallback;
  const system=`You are FindAI's final product identity adjudicator. You receive multiple INDEPENDENT vision-model opinions plus a forensic OCR/physical-evidence report for the SAME user photo. Reconcile them from the pixels/evidence; majority agreement is useful but is not proof. Return one JSON object only:
{"kind":"product|not_product","brand":"","productLine":"","model":"","variant":"","category":"","size":"","visibleText":[],"visualFeatures":[],"canonicalQuery":"","queryVariants":[],"requiredTerms":[],"negativeTerms":[],"confidence":0.0,"needsAnotherAngle":false,"angleRequest":"","reason":""}
Rules:
- Exact identity matters. Separate model family from release/colourway/flanker. Do not call Zebra "Triple Black", Bred, Triple White or Pirate Black merely because all are Yeezy 350s.
- Use visible logos, text, style/model codes, silhouette, pattern, colour blocking, sole, packaging, bottle shape and label layout together.
- For fragrance, distinguish the named line/flanker and concentration when visible. Never infer a 10ml/sample size from unrelated listings.
- For trading cards preserve expansion + product format. For electronics preserve exact model/generation when supported.
- canonicalQuery must be concise, non-repetitive and suitable for exact shopping search. Never output strings like "Yeezy Yeezy 350 ... Yeezy Boost".
- If the independent models disagree on a release/variant, keep the shared product family unless the forensic evidence clearly resolves the conflict; lower confidence so FindAI can visually adjudicate against retrieved candidates.
- requiredTerms must include a confidently resolved release/variant/model code so text-only listing fallbacks cannot silently switch variants.
- Never use marketplace popularity as evidence and never invent hidden size/storage/variant.`;
  try{
    const out=await env.AI.run(FINDAI_IDENTITY_RESOLVER_MODEL,{messages:[{role:'system',content:system},{role:'user',content:JSON.stringify({opinions:list,evidence:evidence||{}}).slice(0,18000)}],max_tokens:700,temperature:0.01});
    const parsed=parseLooseJsonObject(rawAiResponse(out)); if(!parsed)return fallback;
    const confRaw=Number(parsed.confidence),canonical=String(parsed.canonicalQuery||parsed.exactQuery||fallback.canonicalQuery||'').replace(/\s+/g,' ').trim();
    const resolved={kind:String(parsed.kind||fallback.kind||'product').toLowerCase(),brand:String(parsed.brand||fallback.brand||'').trim(),productLine:String(parsed.productLine||fallback.productLine||'').trim(),model:String(parsed.model||fallback.model||'').trim(),variant:String(parsed.variant||fallback.variant||'').trim(),category:String(parsed.category||fallback.category||'').trim(),size:String(parsed.size||fallback.size||'').trim(),visibleText:normaliseFindAIArray(parsed.visibleText||fallback.visibleText,24),visualFeatures:normaliseFindAIArray(parsed.visualFeatures||fallback.visualFeatures,24),canonicalQuery:canonical,queryVariants:[canonical,...normaliseFindAIArray(parsed.queryVariants,6),...normaliseFindAIArray(fallback.queryVariants,6)].filter(Boolean),requiredTerms:normaliseFindAIArray(parsed.requiredTerms||fallback.requiredTerms,14),negativeTerms:normaliseFindAIArray(parsed.negativeTerms||fallback.negativeTerms,12),confidence:Number.isFinite(confRaw)?Math.max(0,Math.min(1,confRaw>1?confRaw/100:confRaw)):fallback.confidence,needsAnotherAngle:parsed.needsAnotherAngle===true,angleRequest:String(parsed.angleRequest||fallback.angleRequest||'').trim(),reason:String(parsed.reason||'').trim()};
    return enrichFindAIIdentity(sanitiseFindAIIdentity(resolved,evidence),evidence);
  }catch(_){return fallback;}
}


async function refineFindAIIdentityFromCandidates(identity, evidence, candidateItems, env) {
  const current = identity && typeof identity === 'object' ? identity : {};
  const items = (Array.isArray(candidateItems) ? candidateItems : []).filter(item => item && item.title).slice(0, 14);
  if (!env || !env.AI || !items.length) return current;
  const system = `You are FindAI's retrieval-assisted product identity resolver. You are given visual/OCR evidence from one user photo plus candidate shopping titles retrieved from the web. The candidate titles are clues, not truth. Identify the photographed product only when the visible evidence supports the candidate identity. Never copy an unsupported size, storage, concentration, edition, colour or model from a listing. Return one JSON object only:
{"kind":"product|not_product","brand":"","productLine":"","model":"","variant":"","category":"","size":"","visibleText":[],"visualFeatures":[],"canonicalQuery":"","queryVariants":[],"requiredTerms":[],"negativeTerms":[],"confidence":0.0,"needsAnotherAngle":false,"angleRequest":"","reason":""}
Rules:
- A clearly visible brand + product-line name is enough for a useful identity even when a hidden size/variant is unknown.
- Preserve visible set/expansion names and product formats such as booster box, Elite Trainer Box, fragrance bottle, console edition or LEGO set number.
- For sneakers/fashion, use candidate titles to name a known colourway/release only when the supplied visual/OCR evidence independently supports that exact appearance. If several candidates agree on the same style/SKU for that visually resolved release, it may be included in canonicalQuery.
- Candidate listings may include accessories, empty packaging, samples or wrong variants; do not let them override the photo evidence.
- If multiple close variants remain plausible, identify the shared exact product family and request another angle only for the unresolved attribute.
- canonicalQuery must be a useful shopping query with at least brand/product line or equally distinctive visible terms.
- confidence is exact-identity confidence, not category confidence.`;
  try {
    const out = await env.AI.run(FINDAI_IDENTITY_RESOLVER_MODEL, {
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: JSON.stringify({
          currentIdentity: current,
          evidence: evidence || {},
          candidates: items.map((item, index) => ({ id:index, title:String(item.title||'').slice(0,240), source:String(item.retailer||item.source||'').slice(0,80) }))
        }).slice(0, 15000) }
      ],
      max_tokens: 700,
      temperature: 0.02
    });
    const parsed = parseLooseJsonObject(rawAiResponse(out));
    if (!parsed) return current;
    const refined = fallbackFindAIIdentity({
      ...parsed,
      exactQuery: parsed.canonicalQuery || parsed.exactQuery,
      candidateNames: parsed.queryVariants
    }, evidence);
    refined.queryVariants = normaliseFindAIArray(parsed.queryVariants, 6);
    refined.requiredTerms = normaliseFindAIArray(parsed.requiredTerms, 14);
    refined.negativeTerms = normaliseFindAIArray(parsed.negativeTerms, 12);
    refined.reason = String(parsed.reason || '').trim();
    return mergeFindAIIdentityEvidence(refined, current, evidence);
  } catch (_) {
    return current;
  }
}

async function refineFindAIIdentityFromVisualCandidates(identity,evidence,candidateItems,originalBytes,env){
  const current=sanitiseFindAIIdentity(identity||{},evidence);
  const semantic=prepareFindAIListingCandidates(candidateItems,current,[current.canonicalQuery].filter(Boolean));
  const selected=selectFindAIVisualCandidates(semantic,8);
  if(!selected.length||!originalBytes||!env||!env.AI)return current;
  const comparisons=await promiseWithin(compareFindAIDirectImagesBatched(originalBytes,selected,current,evidence,env),10500,new Map());
  const visuallySupported=[];
  selected.forEach((item,index)=>{
    const hit=comparisons.get(String(index));
    if(!hit)return;
    const st=String(hit.status||''),score=Number(hit.score);
    if((st==='same'&&score>=0.70)||(st==='possible'&&score>=0.82))visuallySupported.push({...item,_visualIdentityDecision:st,_visualIdentityScore:score});
  });
  if(!visuallySupported.length)return current;
  const refined=await refineFindAIIdentityFromCandidates(current,evidence,visuallySupported.slice(0,8),env);
  if(!refined||typeof refined!=='object')return current;
  refined._visualAdjudicated=true;
  refined._visualAdjudicationCandidates=visuallySupported.length;
  return sanitiseFindAIIdentity(refined,evidence);
}

async function identifyFindAIProduct(bytesOrImages, env) {
  const images=findAIImageInputs(bytesOrImages), primaryBytes=images[0]||[];
  const calls=[
    promiseWithin(runFindAIVisionJson(images,FINDAI_SCAN_PRIMARY_PROMPT,env,900,FINDAI_PRIMARY_VISION_MODEL),9000,{data:null,error:'Llama 4 vision timed out'}),
    promiseWithin(runFindAIVisionJson(images,FINDAI_SCAN_PRIMARY_PROMPT,env,900,FINDAI_SECONDARY_VISION_MODEL),9000,{data:null,error:'Gemma vision timed out'}),
    promiseWithin(runFindAIVisionJson(primaryBytes,FINDAI_SCAN_EVIDENCE_PROMPT,env,820,FINDAI_OCR_VISION_MODEL),8000,{data:null,error:'OCR evidence timed out'})
  ];
  if(findAIFrontierVisionEnabled(env))calls.push(promiseWithin(runFindAIVisionJson(images,FINDAI_SCAN_PRIMARY_PROMPT,env,900,FINDAI_FRONTIER_VISION_MODEL),6500,{data:null,error:'Frontier vision unavailable or timed out'}));
  const settled=await Promise.allSettled(calls);
  const wraps=settled.map(x=>x.status==='fulfilled'?x.value:{data:null,error:String(x.reason||'')});
  const evidenceWrap=wraps[2]||{},evidence=evidenceWrap.data||{};
  const opinionWraps=[wraps[0],wraps[1],...(wraps.length>3?[wraps[3]]:[])].filter(Boolean);
  const opinions=opinionWraps.map(x=>x&&x.data).filter(Boolean);
  let provisional={kind:'product',brand:'',productLine:'',model:'',variant:'',category:'',size:'',visibleText:[],canonicalQuery:'',queryVariants:[],requiredTerms:[],negativeTerms:[],confidence:null};
  for(const raw of opinions){
    const candidate=enrichFindAIIdentity(fallbackFindAIIdentity(raw,evidence),evidence);
    if(findAIIdentityQuality(candidate,evidence).score>findAIIdentityQuality(provisional,evidence).score)provisional=candidate;
  }
  let quality=findAIIdentityQuality(provisional,evidence),fallbackError='';
  if(!opinions.length||!quality.valid){
    const legacy=await runFindAIVisionJson(primaryBytes,STRUCTURED_PRODUCT_VISION_PROMPT,env,620,VISION_MODEL); fallbackError=String(legacy&&legacy.error||'');
    if(legacy&&legacy.data){const legacyIdentity=fallbackFindAIIdentity({...legacy.data,exactQuery:legacy.data.exactQuery||legacy.data.query,candidateNames:[legacy.data.exactQuery||legacy.data.query].filter(Boolean)},evidence);opinions.push(legacy.data);provisional=mergeFindAIIdentityEvidence(provisional,legacyIdentity,evidence);}
  }
  let identity=await resolveFindAIIdentity(opinions.length?opinions:[provisional],evidence,env);
  identity=mergeFindAIIdentityEvidence(identity,provisional,evidence);
  const consensus=findAIIdentityConsensus(opinions,evidence);
  identity=sanitiseFindAIIdentity({...identity,_ensembleConsensus:consensus.score,_ensembleDisagreement:consensus.disagreement},evidence);
  quality=findAIIdentityQuality(identity,evidence);
  if(!quality.valid&&String(identity.kind||'product')!=='not_product'){
    const fast=await identifyFindAIProductFast(primaryBytes,env,true);
    if(fast&&fast.identity){identity=sanitiseFindAIIdentity(mergeFindAIIdentityEvidence(fast.identity,identity,evidence||fast.evidence),evidence||fast.evidence);quality=findAIIdentityQuality(identity,evidence||fast.evidence);}
  }
  return {identity,evidence:evidence||{},quality,consensus,errors:[...opinionWraps.map(x=>x&&x.error),evidenceWrap&&evidenceWrap.error,fallbackError].filter(Boolean)};
}


function findAIQueryVariants(identity, evidence) {
  const supplied = normaliseFindAIArray(identity && identity.queryVariants, 6);
  const canonical = String(identity && identity.canonicalQuery || '').trim();
  const category = String(identity && identity.category || '').trim();
  const physicalForm = String(evidence && (evidence.primaryObject || evidence.productForm) || '').trim();
  const abbreviated = findAIAbbreviatedQuery(canonical);
  const visibleOnly = findAIDistinctiveVisiblePhrases(identity, evidence).join(' ');
  const composed = [
    canonical,
    abbreviated,
    [identity && identity.brand, visibleOnly].filter(Boolean).join(' '),
    [identity && identity.brand, identity && identity.productLine, identity && identity.model, identity && identity.variant, identity && identity.size, category].filter(Boolean).join(' '),
    [canonical, physicalForm].filter(Boolean).join(' ')
  ];
  const seen = new Set();
  return [...composed, ...supplied].map(v => String(v || '').replace(/\s+/g, ' ').trim()).filter(v => {
    const key = hybridNormalise(v);
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return hybridTokens(v, true).length >= 2;
  }).slice(0, 3);
}

function findAIListingTotal(item) {
  const price = Number(item && item.price);
  if (!(price > 0)) return Infinity;
  const shipping = Number(item && item.shippingCost);
  return price + (Number.isFinite(shipping) && shipping > 0 ? shipping : 0);
}

const FINDAI_LISTING_FORM_RE = /\b(case\s*only|box\s*only|bottle\s*only|container\s*only|packaging\s*only|empty\s*(?:box|bottle|container|packet|packaging)|replacement\s*(?:part|parts|strap|case|lid|cap|cable|charger|remote)|parts?\s*only|manual\s*only|instructions?\s*only|no\s+contents?|contents?\s+not\s+included|display\s+only|sample|decant|miniature|tester|refill|replica|compatible\s+with|for\s+parts|damaged|broken)\b/i;
const FINDAI_PRINTED_MEDIA_RE = /\b(magazine(?:s)?|advert(?:isement|ising)?|adverts?|print\s*ad|clippings?|poster|brochure|catalog(?:ue)?|flyer|leaflet|press\s*photo|promo(?:tional)?\s*(?:photo|card|print)|paper\s*ephemera)\b/i;
const FINDAI_ACCESSORY_RE = /\b(key\s*ring|keychain|key\s*chain|charm|lapel\s*pin|pin\s*badge|magnet|sticker|decal|dust\s*bag|storage\s*bag|shoe\s*box|empty\s*box|strap\s*only|case\s*only|cover\s*only|stand\s*only|stand\s*base|base\s*stand|table\s*stand|pedestal\s*stand|tv\s*(?:feet|legs)|replacement\s*(?:feet|legs|stand)|mount\s*only|mounting\s*bracket|wall\s*mount|charger\s*only|cable\s*only|remote\s*only|manual\s*only|instructions?\s*only|replacement\s*part|spare\s*part|parts?\s*only|screws?\s*(?:set|kit|pack))\b/i;
const FINDAI_EMPTY_SEPARATED_RE = /\bempty\b.{0,90}\b(box|bottle|container|packet|packaging|case|carton)\b|\b(box|bottle|container|packet|packaging|case|carton)\b.{0,45}\b(?:empty|only)\b/i;
const FINDAI_NO_CONTENTS_RE = /\b(?:no\s+contents?|contents?\s+(?:not\s+included|removed|missing)|packaging\s+only|display\s+box\s+only|collector(?:'s|s)?\s+box\s+only)\b/i;

function findAITargetAllowsPrintedMedia(identity) {
  const text = hybridNormalise([identity && identity.category, identity && identity.canonicalQuery, identity && identity.productLine].filter(Boolean).join(' '));
  return /\b(book|magazine|poster|print|advertisement|brochure|catalogue|trading card|photocard|comic|newspaper)\b/.test(text);
}

function findAITargetExplicitlyEmpty(identity) {
  const target = hybridNormalise([identity && identity.canonicalQuery, identity && identity.productLine, identity && identity.model, identity && identity.variant].filter(Boolean).join(' '));
  return /\bempty\b/.test(target);
}
function findAIListingFormHint(title, identity) {
  const text = String(title || '');
  if (FINDAI_PRINTED_MEDIA_RE.test(text) && !findAITargetAllowsPrintedMedia(identity)) return 'advertisement_or_printed_media';
  if (!findAITargetExplicitlyEmpty(identity) && (FINDAI_EMPTY_SEPARATED_RE.test(text) || FINDAI_NO_CONTENTS_RE.test(text))) return 'packaging_or_empty_container';
  if (/\b(empty\s*(?:box|bottle|container)|box\s*only|bottle\s*only|container\s*only|packaging\s*only)\b/i.test(text)) return 'packaging_or_empty_container';
  if (/\b(sample|decant|miniature|tester|vial|travel\s*spray)\b/i.test(text)) return 'sample_or_miniature';
  if (FINDAI_ACCESSORY_RE.test(text)) return 'accessory_or_replacement_part';
  if (/\b(replica|reproduction|inspired\s*by|dupe|fake)\b/i.test(text)) return 'replica_or_imitation';
  if (FINDAI_LISTING_FORM_RE.test(text)) return 'non_complete_product';
  return 'complete_or_unclear';
}


// Exact-title rescue path. Direct image verification is still the preferred
// signal, but marketplace thumbnails can time out, be blocked, or be too small
// for a multimodal model. A popular, precisely identified product must not turn
// into an empty screen merely because that optional verification call failed.
// This fallback is deliberately strict and only activates for identities with
// distinctive visible evidence (model/set/edition/variant/size), never for a
// broad identity such as "Ralph Lauren cologne" or "LEGO Harry Potter".
const FINDAI_GENERIC_IDENTITY_TOKENS = new Set([
  'the','and','for','with','from','new','used','genuine','authentic','official','original',
  'product','item','model','edition','version','brand','men','mens','women','womens','unisex',
  'trading','card','cards','game','games','tcg','collectible','collectibles',
  'elite','trainer','box','set','collection','pack','sealed',
  'eau','de','parfum','perfume','fragrance','cologne','spray','toilette','edp','edt',
  'lego','pokemon','pokémon'
]);

function findAINormalisedTitle(value) {
  return hybridNormalise(String(value || '')
    .replace(/\bfl\.?\s*oz\.?\b/ig, ' oz ')
    .replace(/\beau\s+de\s+parfum\b/ig, ' edp ')
    .replace(/\beau\s+de\s+toilette\b/ig, ' edt ')
    .replace(/\belite\s+trainer\s+box\b/ig, ' etb '));
}

function findAIExtractSizeMl(value) {
  const text = String(value || '').toLowerCase();
  const ml = text.match(/(?:^|\D)(\d{2,4}(?:\.\d+)?)\s*ml\b/);
  if (ml) return Number(ml[1]);
  const oz = text.match(/(?:^|\D)(\d(?:\.\d+)?)\s*(?:fl\.?\s*)?oz\b/);
  if (oz) return Number(oz[1]) * 29.5735;
  return null;
}

function findAISizeCompatibility(title, identity) {
  const target = findAIExtractSizeMl(identity && identity.size);
  if (!(target > 0)) return { compatible: true, stated: false, exact: false };
  const listing = findAIExtractSizeMl(title);
  if (!(listing > 0)) return { compatible: true, stated: false, exact: false };
  const tolerance = Math.max(4, target * 0.07);
  return { compatible: Math.abs(listing - target) <= tolerance, stated: true, exact: Math.abs(listing - target) <= tolerance };
}

function findAIConcentration(value) {
  const text = findAINormalisedTitle(value);
  if (/\bparfum\b/.test(text) && !/\bedp\b/.test(text)) return 'parfum';
  if (/\bedp\b/.test(text)) return 'edp';
  if (/\bedt\b/.test(text)) return 'edt';
  if (/\bcologne\b/.test(text)) return 'cologne';
  return '';
}

function findAIConcentrationCompatibility(title, identity) {
  const target = findAIConcentration([identity && identity.variant, identity && identity.productLine, identity && identity.canonicalQuery].filter(Boolean).join(' '));
  if (!target) return { compatible: true, stated: false, exact: false };
  const listing = findAIConcentration(title);
  if (!listing) return { compatible: true, stated: false, exact: false };
  return { compatible: listing === target, stated: true, exact: listing === target };
}

function findAIProductFormatCompatibility(title, identity, evidence) {
  const target = findAINormalisedTitle([
    identity && identity.canonicalQuery,
    identity && identity.productLine,
    identity && identity.model,
    identity && identity.variant,
    evidence && evidence.productForm,
    evidence && evidence.primaryObject
  ].filter(Boolean).join(' '));
  const listing = findAINormalisedTitle(title);
  const formatRules = [
    [/\betb\b/, /\betb\b/],
    [/\bbooster\s+box\b/, /\bbooster\s+(?:display\s+)?box\b/],
    [/\bbooster\s+bundle\b/, /\bbooster\s+bundle\b/],
    [/\bcollection\s+box\b/, /\bcollection\s+box\b/],
    [/\belite\s+trainer\s+box\b/, /\betb\b/]
  ];
  for (const [targetRe, listingRe] of formatRules) {
    if (targetRe.test(target) && !listingRe.test(listing)) return false;
  }
  return true;
}

function findAIIdentitySpecificity(identity, evidence) {
  const brandTokens = new Set(hybridTokens(identity && identity.brand || '', true));
  const source = [
    identity && identity.productLine,
    identity && identity.model,
    identity && identity.variant,
    identity && identity.canonicalQuery,
    ...(normaliseFindAIArray(identity && identity.requiredTerms, 20)),
    ...(findAIDistinctiveVisiblePhrases(identity, evidence))
  ].filter(Boolean).join(' ');
  const tokens = hybridTokens(source, true).filter(t => t.length > 2 && !brandTokens.has(t) && !FINDAI_GENERIC_IDENTITY_TOKENS.has(t));
  const unique = [...new Set(tokens)];
  const numeric = hybridTokens(source, false).filter(t => /\d/.test(t) && t.length >= 3);
  const hasFormat = /\b(?:elite\s+trainer\s+box|etb|booster\s+box|booster\s+bundle|collection\s+box)\b/i.test(source);
  const hasSize = findAIExtractSizeMl(identity && identity.size) > 0;
  const hasConcentration = !!findAIConcentration(source);
  const specific = unique.length >= 2 || numeric.length >= 1 || (unique.length >= 1 && (hasFormat || hasSize || hasConcentration));
  return { specific, tokens: unique.slice(0, 10), numeric: [...new Set(numeric)].slice(0, 6), hasFormat, hasSize, hasConcentration };
}

function findAIOriginalLooksFullSizeFragrance(identity,evidence){
  const source=hybridNormalise([identity&&identity.category,identity&&identity.productLine,identity&&identity.model,evidence&&evidence.productForm,evidence&&evidence.primaryObject].filter(Boolean).join(' '));
  if(!/\b(?:beauty|fragrance|perfume|cologne|eau de parfum|eau de toilette|parfum)\b/.test(source))return false;
  const tiny=findAIExtractSizeMl(identity&&identity.size);
  if(tiny>0&&tiny<=15)return false;
  const ev=hybridNormalise([evidence&&evidence.productForm,evidence&&evidence.primaryObject,...normaliseFindAIArray(evidence&&evidence.distinctiveFeatures,12)].filter(Boolean).join(' '));
  return !/\b(?:sample|miniature|mini|travel|vial|decant)\b/.test(ev);
}
function findAIVariantTextCompatibility(title,identity,evidence,strict=true){
  const t=hybridNormalise(title||''); if(!t)return false;
  // Never let a tiny sample/travel atomiser define the price of a normal photographed bottle.
  if(findAIOriginalLooksFullSizeFragrance(identity,evidence)){
    const ml=[...String(title||'').matchAll(/(?:^|\b)(\d+(?:\.\d+)?)\s*ml\b/ig)].map(m=>Number(m[1])).filter(Number.isFinite);
    if(ml.length&&Math.max(...ml)<=15)return false;
    if(/\b(?:sample|tester vial|vial|decant|travel spray|miniature)\b/i.test(String(title||'')))return false;
  }
  const variant=String(identity&&identity.variant||'').trim();
  const variantTokens=hybridTokens(variant,true).filter(x=>x.length>1&&!FINDAI_GENERIC_IDENTITY_TOKENS.has(x));
  if(variantTokens.length){
    const hit=variantTokens.filter(x=>webDiscoveryTitleHasQueryToken(' '+t+' ',x)).length;
    const need=variantTokens.length<=2?variantTokens.length:Math.ceil(variantTokens.length*0.72);
    if(hit<need)return false;
  }
  const modelCodes=[...normaliseFindAIArray(evidence&&evidence.modelNumbers,12),...normaliseFindAIArray(identity&&identity.requiredTerms,14)]
    .map(x=>String(x||'').trim()).filter(x=>/^(?=.*\d)(?=.*[a-z])[a-z0-9-]{4,}$/i.test(x));
  if(strict&&modelCodes.length){
    const titleFlat=t.replace(/\s+/g,'');
    const hasCode=modelCodes.some(code=>titleFlat.includes(hybridNormalise(code).replace(/\s+/g,'')));
    // A code is definitive when present in the title. If the title omits every code, a
    // resolved human-readable variant can still qualify; otherwise text-only is too risky.
    if(!hasCode&&!variantTokens.length)return false;
  }
  return true;
}

function findAIExactTextMatch(item, identity, evidence) {
  if (!item || !item.title || !(Number(item.price) > 0)) return null;
  const formHint = findAIListingFormHint(item.title, identity);
  if (formHint !== 'complete_or_unclear') return null;
  const specificity = findAIIdentitySpecificity(identity, evidence);
  if (!specificity.specific) return null;

  const titleNorm = findAINormalisedTitle(item.title);
  const titleTokens = new Set(hybridTokens(titleNorm, true));
  const brandTokens = hybridTokens(identity && identity.brand || '', true);
  if (brandTokens.length && brandTokens.filter(t => titleTokens.has(t)).length / brandTokens.length < 0.5) return null;

  const tokenHits = specificity.tokens.filter(t => titleTokens.has(t)).length;
  const requiredRatio = specificity.tokens.length <= 2 ? 1 : (specificity.tokens.length <= 4 ? 0.75 : 0.64);
  if (specificity.tokens.length && tokenHits / specificity.tokens.length < requiredRatio) return null;
  if (specificity.numeric.length && !specificity.numeric.every(t => titleNorm.includes(hybridNormalise(t)))) return null;
  if (!findAIProductFormatCompatibility(item.title, identity, evidence)) return null;
  if (!findAIVariantTextCompatibility(item.title, identity, evidence, true)) return null;

  const size = findAISizeCompatibility(item.title, identity);
  if (!size.compatible) return null;
  const concentration = findAIConcentrationCompatibility(item.title, identity);
  if (!concentration.compatible) return null;

  const scored = findAIListingScore(item, identity, [identity && identity.canonicalQuery].filter(Boolean));
  if (scored.queryCoverage < 0.46 && scored.requiredCoverage < 0.58) return null;

  let confidence = 0.76;
  confidence += Math.min(0.10, (specificity.tokens.length ? tokenHits / specificity.tokens.length : 0) * 0.10);
  if (specificity.numeric.length) confidence += 0.05;
  if (size.exact) confidence += 0.03;
  if (concentration.exact) confidence += 0.03;
  if (specificity.hasFormat) confidence += 0.03;
  confidence = Math.min(0.94, confidence);
  return { confidence, reason: 'Distinctive product identity and listing title agree' };
}

function findAIExactTextFallbackCandidates(candidates, identity, evidence, excludeKeys = new Set()) {
  const out = [];
  for (const item of Array.isArray(candidates) ? candidates : []) {
    const key = hybridListingKey(item);
    if (!key || excludeKeys.has(key)) continue;
    const exact = findAIExactTextMatch(item, identity, evidence);
    if (!exact) continue;
    out.push({
      ...item,
      _findaiMatchMethod: 'exact-text',
      _findaiMatchScore: exact.confidence,
      _findaiVisualStatus: 'not-run',
      _findaiVisualScore: null,
      _findaiVisualForm: 'complete_product',
      _findaiVisualReason: exact.reason
    });
  }
  out.sort((a, b) => {
    const ca = Number(a._findaiMatchScore) || 0, cb = Number(b._findaiMatchScore) || 0;
    if (ca !== cb) return cb - ca;
    return findAIListingTotal(a) - findAIListingTotal(b);
  });
  return out.slice(0, 12);
}

function findAIListingScore(item, identity, queries) {
  const title = String(item && item.title || '');
  const titleNorm = hybridNormalise(title);
  const titleTokens = new Set(hybridTokens(title, true));
  const required = hybridTokens(normaliseFindAIArray(identity && identity.requiredTerms).join(' '), true);
  const brand = hybridTokens(identity && identity.brand || '', true);
  const model = hybridTokens(identity && identity.model || '', true);
  const product = hybridTokens(identity && identity.productLine || '', true);
  const variant = hybridTokens(identity && identity.variant || '', true);
  const coverage = tokens => tokens.length ? tokens.filter(t => titleTokens.has(t)).length / tokens.length : 0;
  const queryCoverage = Math.max(0, ...(queries || []).map(q => coverage(hybridTokens(q, true))));
  const requiredCoverage = coverage(required);
  let score = queryCoverage * 85 + requiredCoverage * 115 + coverage(product) * 70 + coverage(model) * 85 + coverage(variant) * 45 + coverage(brand) * 28;
  const exactPhrases = [identity && identity.productLine, identity && identity.model, identity && identity.variant, identity && identity.canonicalQuery].filter(v => String(v || '').trim().length >= 3);
  for (const phrase of exactPhrases) if (titleNorm.includes(hybridNormalise(phrase))) score += 26;
  const negativeTerms = normaliseFindAIArray(identity && identity.negativeTerms);
  for (const term of negativeTerms) if (titleNorm.includes(hybridNormalise(term))) score -= 65;
  const formHint = findAIListingFormHint(title, identity);
  const formPenalty = formHint !== 'complete_or_unclear';
  if (formPenalty) score -= formHint === 'advertisement_or_printed_media' ? 180 : 120;
  if (item && item.image) score += 3;
  return { score, queryCoverage, requiredCoverage, formPenalty, formHint };
}

function prepareFindAIListingCandidates(items, identity, queries) {
  const deduped = [];
  const seen = new Set();
  for (const item of Array.isArray(items) ? items : []) {
    if (!item || !item.title || !(Number(item.price) > 0)) continue;
    const key = hybridListingKey(item);
    if (seen.has(key)) continue;
    seen.add(key);
    const scored = findAIListingScore(item, identity, queries);
    if (scored.formHint === 'advertisement_or_printed_media' || scored.formHint === 'packaging_or_empty_container' || scored.formHint === 'accessory_or_replacement_part' || scored.formHint === 'replica_or_imitation') continue;
    deduped.push({ ...item, _findaiScore: scored.score, _findaiQueryCoverage: scored.queryCoverage, _findaiRequiredCoverage: scored.requiredCoverage, _findaiFormPenalty: scored.formPenalty, _findaiFormHint: scored.formHint, totalPrice: findAIListingTotal(item) });
  }
  deduped.sort((a, b) => (b._findaiScore || 0) - (a._findaiScore || 0));
  if (!deduped.length) return [];
  const topScore = Number(deduped[0]._findaiScore) || 0;
  const hasDistinctiveTerms = hybridTokens([identity && identity.productLine, identity && identity.model, ...(identity && identity.requiredTerms || [])].join(' '), true).length >= 2;
  const floor = Math.max(hasDistinctiveTerms ? 54 : 34, topScore - (hasDistinctiveTerms ? 42 : 56));
  let qualified = deduped.filter(item => item._findaiScore >= floor && (item._findaiQueryCoverage >= (hasDistinctiveTerms ? 0.42 : 0.28) || item._findaiRequiredCoverage >= 0.58));
  if (qualified.length < 6) qualified = deduped.filter(item => item._findaiScore >= Math.max(34, topScore - 52)).slice(0, 24);
  return qualified.slice(0, 60);
}

function selectFindAIVisualCandidates(candidates, limit = FINDAI_VISUAL_CANDIDATE_LIMIT) {
  // Accuracy first, but never let one marketplace occupy every visual-verifier slot.
  // A scan is web-wide: reserve room for distinct retailer hosts so JB Hi-Fi, Apple,
  // fragrance stores, hobby retailers, etc. can be compared against the source photo.
  const byScore = [...candidates].sort((a, b) => (b._findaiScore || 0) - (a._findaiScore || 0));
  const byNaturalRank = [...candidates].sort((a, b) => {
    const aq = Number(a._findaiQueryRank) || 0, bq = Number(b._findaiQueryRank) || 0;
    if (aq !== bq) return aq - bq;
    return (Number(a._findaiResultRank) || 0) - (Number(b._findaiResultRank) || 0);
  });
  const pool = [...byScore.slice(0, 36), ...byNaturalRank.slice(0, 36)];
  const selected = [], seen = new Set(), sourceCounts = new Map();
  const add = (item, perSourceCap) => {
    const key = hybridListingKey(item), source = findAIScanSourceKey(item);
    if (!key || seen.has(key) || !item.image) return false;
    const used = sourceCounts.get(source) || 0;
    if (used >= perSourceCap) return false;
    seen.add(key); sourceCounts.set(source, used + 1); selected.push(item); return true;
  };
  // Pass 1: one image per source. This is the critical web-retailer diversity pass.
  for (const item of pool) { add(item, 1); if (selected.length >= limit) return selected; }
  // Pass 2: allow up to three strong images from any one source.
  for (const item of pool) { add(item, 3); if (selected.length >= limit) return selected; }
  // Pass 3: fill any remaining slots without a source cap.
  for (const item of pool) {
    const key = hybridListingKey(item); if (!key || seen.has(key) || !item.image) continue;
    seen.add(key); selected.push(item); if (selected.length >= limit) break;
  }
  return selected;
}

async function fetchFindAIListingImageBytes(imageUrl) {
  if (!imageUrl || !/^https?:\/\//i.test(String(imageUrl))) return null;
  let response = null;
  try {
    response = await promiseWithin(fetch(String(imageUrl), {
      headers: { 'User-Agent': 'FindAI-Listing-Verifier/2.0', 'Accept': 'image/avif,image/webp,image/jpeg,image/png,image/*' },
      cf: { image: { width: 512, height: 512, fit: 'scale-down', quality: 72, format: 'jpeg' } }
    }), 2400, null);
  } catch (_) {}
  if (!response || !response.ok) return null;
  try {
    const buffer = await response.arrayBuffer();
    if (!buffer || buffer.byteLength < 200 || buffer.byteLength > 1_500_000) return null;
    return new Uint8Array(buffer);
  } catch (_) { return null; }
}

function findAIBytesDataUrl(bytes) {
  const arr = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes || []);
  return 'data:image/jpeg;base64,' + bytesToBase64(arr);
}

async function compareFindAIDirectImages(originalBytes, selected, identity, evidence, env, idOffset = 0) {
  const map = new Map();
  if (!env || !env.AI || !originalBytes || !selected.length) return map;

  const fetched = await Promise.all(selected.map(async (item, index) => ({
    index: idOffset + index,
    item,
    bytes: await fetchFindAIListingImageBytes(item && item.image)
  })));
  const available = fetched.filter(row => row.bytes);
  if (!available.length) return map;

  const parts = [{
    type: 'text',
    text: `You are FindAI's product-image matcher. Image 1 is the user's original scan. Every later image is one live shopping candidate from a retailer or marketplace, in the labelled order below. Compare the physical objects directly, not merely the titles. Return one JSON object only in this exact shape: {"results":[{"id":"0","decision":"same|possible|different|not_product","score":0.0,"form":"complete_product|bundle_or_lot|accessory_or_part|printed_media|packaging_only|sample_or_miniature|different_product|unclear","reason":""}]}.

Accept different backgrounds, lighting, crop, normal retail packaging presence and camera angle when the underlying sellable product is the same. Read any large overlay/label text on candidate images. Reject candidates marked EMPTY BOX, EMPTY BOTTLE, BOX ONLY, BOTTLE ONLY, NO CONTENTS or similar even when the packaging visually matches. Reject keyrings, charms, advertisements, magazine clippings, posters, empty packaging, empty containers, samples, loose parts, accessories and unrelated bundles. An assembled LEGO build is not a loose-minifigure lot. A fragrance bottle is not branded merchandise. A correct title cannot rescue a visibly different object. Use possible only for the same physical product where a hidden size or variant cannot be confirmed. Include one result for every candidate id.

Known identity: ${JSON.stringify({ brand: identity && identity.brand || '', productLine: identity && identity.productLine || '', model: identity && identity.model || '', variant: identity && identity.variant || '', category: identity && identity.category || '', size: identity && identity.size || '', visibleText: normaliseFindAIArray(identity && identity.visibleText, 16), originalForm: evidence && (evidence.primaryObject || evidence.productForm) || '', originalFeatures: normaliseFindAIArray(evidence && evidence.distinctiveFeatures, 12) }).slice(0, 5000)}`
  }, {
    type: 'image_url',
    image_url: { url: findAIBytesDataUrl(originalBytes) }
  }];

  for (const row of available) {
    parts.push({ type: 'text', text: `Candidate id ${row.index}: ${String(row.item && row.item.title || '').slice(0, 240)}` });
    parts.push({ type: 'image_url', image_url: { url: findAIBytesDataUrl(row.bytes) } });
  }

  try {
    const out = await promiseWithin(env.AI.run(FINDAI_VISUAL_MATCH_MODEL, {
      messages: [{ role: 'user', content: parts }],
      max_tokens: 1100,
      temperature: 0,
      chat_template_kwargs: { thinking: false }
    }), 12000, null);
    if (!out) return map;
    const parsed = parseLooseJsonObject(rawAiResponse(out));
    for (const row of Array.isArray(parsed && parsed.results) ? parsed.results : []) {
      const rawScore = Number(row && row.score);
      map.set(String(row && row.id), {
        status: String(row && row.decision || 'unverified').toLowerCase(),
        score: Number.isFinite(rawScore) ? Math.max(0, Math.min(1, rawScore > 1 ? rawScore / 100 : rawScore)) : null,
        form: String(row && row.form || 'unclear').toLowerCase(),
        reason: String(row && row.reason || '').slice(0, 240)
      });
    }
  } catch (_) {}
  return map;
}

const FINDAI_CANDIDATE_FINGERPRINT_PROMPT = `You are FindAI's visual fingerprint reader. Analyse only the supplied marketplace image. Do not use a title or infer an identity from brand popularity. Return one JSON object only:
{"productForm":"","primaryObject":"","objectCount":1,"isBundle":false,"isCompleteSellableItem":true,"isAccessory":false,"isPrintedMedia":false,"isPackagingOnly":false,"isEmptyContainer":false,"isSampleOrMiniature":false,"visibleText":[],"logos":[],"colours":[],"materials":[],"shape":"","silhouette":"","logoPlacement":[],"textPlacement":[],"relativeLayout":[],"distinctiveGeometry":[],"distinctiveFeatures":[]}
Be literal about the physical object. Distinguish a bottle from a keyring, an assembled LEGO build from loose minifigures, a handbag from a strap, a console from a controller, and a real product from a magazine clipping, advert, box or accessory. If the image shows a lot or bundle of multiple items, set isBundle true and give the main object count.`;

async function extractFindAIListingFingerprint(item, env) {
  const imageBytes = await fetchFindAIListingImageBytes(item && item.image);
  if (!imageBytes || !env || !env.AI) return { fingerprint: null, error: 'Image unavailable' };
  const result = await promiseWithin(runFindAIVisionJson(imageBytes, FINDAI_CANDIDATE_FINGERPRINT_PROMPT, env, 420), 9000, { data: null, error: 'Visual fingerprint timed out' });
  return { fingerprint: result && result.data || null, error: String(result && result.error || '') };
}

function findAIFingerprintHardConflict(fp) {
  if (!fp || typeof fp !== 'object') return true;
  if (fp.isAccessory === true || fp.isPrintedMedia === true || fp.isPackagingOnly === true || fp.isEmptyContainer === true || fp.isSampleOrMiniature === true) return true;
  const form = hybridNormalise([fp.productForm, fp.primaryObject].filter(Boolean).join(' '));
  const visible = hybridNormalise(normaliseFindAIArray(fp.visibleText, 30).join(' '));
  if (/\b(empty box|empty bottle|box only|bottle only|packaging only|no contents|contents not included|display only)\b/.test(visible)) return true;
  return /\b(keyring|key chain|keychain|magazine|advertisement|clipping|poster|brochure|empty box|empty bottle|box only|bottle only|packaging only|strap only|case only|replacement part|sample|miniature|decant|loose parts)\b/.test(form);
}

async function compareFindAIVisualFingerprints(selected, fingerprintWraps, identity, evidence, env) {
  if (!env || !env.AI) return new Map();
  const original = {
    identity: {
      brand: identity && identity.brand || '', productLine: identity && identity.productLine || '', model: identity && identity.model || '',
      variant: identity && identity.variant || '', category: identity && identity.category || '', size: identity && identity.size || '',
      visibleText: normaliseFindAIArray(identity && identity.visibleText, 20), visualFeatures: normaliseFindAIArray(identity && identity.visualFeatures, 20)
    },
    visualFingerprint: evidence || {}
  };
  const candidates = selected.map((item, index) => ({
    id: String(index),
    title: String(item && item.title || '').slice(0, 320),
    semanticScore: Number(item && item._findaiScore) || 0,
    fingerprint: fingerprintWraps[index] && fingerprintWraps[index].fingerprint || null
  }));
  const system = `You are FindAI's strict visual twin matcher. Compare one original product-photo fingerprint with candidate marketplace-image fingerprints. Return one JSON object only:
{"results":[{"id":"0","decision":"same|possible|different|not_product","score":0.0,"form":"complete_product|bundle_or_lot|accessory_or_part|printed_media|packaging_only|sample_or_miniature|different_product|unclear","reason":""}]}
Rules:
- The candidate must depict the same physical sellable item, not merely the same brand or words.
- Physical form, silhouette, object count, proportions, part layout, label/logo placement, colours and distinctive geometry outweigh title wording.
- A fragrance bottle versus a branded keyring is different. An assembled LEGO build versus loose figures is different. A handbag versus a strap or dust bag is different. A product versus an advert, clipping, poster, box or empty container is different.
- A bundle or lot is different unless the original photo itself clearly shows that same bundle.
- Use possible only when the candidate is visually the same product family but an exact hidden variant cannot be confirmed. Do not use possible for form conflicts.
- score measures visual identity confidence. Correct title text cannot rescue a visually different object.
- Include one result for every supplied candidate id.`;
  try {
    const out = await env.AI.run(FINDAI_VISUAL_COMPARISON_MODEL, {
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: JSON.stringify({ original, candidates }).slice(0, 30000) }
      ],
      max_tokens: 1600,
      temperature: 0.01
    });
    const parsed = parseLooseJsonObject(rawAiResponse(out));
    const map = new Map();
    for (const row of Array.isArray(parsed && parsed.results) ? parsed.results : []) {
      const rawScore = Number(row && row.score);
      map.set(String(row && row.id), {
        status: String(row && row.decision || 'unverified').toLowerCase(),
        score: Number.isFinite(rawScore) ? Math.max(0, Math.min(1, rawScore > 1 ? rawScore / 100 : rawScore)) : null,
        form: String(row && row.form || 'unclear').toLowerCase(),
        reason: String(row && row.reason || '').slice(0, 240)
      });
    }
    return map;
  } catch (_) {
    return new Map();
  }
}

function findAIVisualAccepted(result, item, topSemanticScore) {
  const form = String(result && result.form || 'unclear');
  if (/advertisement|printed_media|packaging_only|accessory|part|sample|miniature|different_product|bundle_or_lot|not_product/.test(form)) return false;
  if (result && result.status === 'same' && Number(result.score) >= 0.62) return true;
  if (result && result.status === 'possible' && Number(result.score) >= 0.72 && Number(item && item._findaiScore) >= topSemanticScore - 20) return true;
  return false;
}

async function compareFindAIDirectImagesBatched(originalBytes, selected, identity, evidence, env) {
  const batches = [];
  for (let offset = 0; offset < selected.length; offset += FINDAI_VISUAL_BATCH_SIZE) {
    batches.push({ offset, items: selected.slice(offset, offset + FINDAI_VISUAL_BATCH_SIZE) });
  }
  const results = await Promise.all(batches.map(batch =>
    compareFindAIDirectImages(originalBytes, batch.items, identity, evidence, env, batch.offset)
  ));
  const merged = new Map();
  for (const result of results) for (const [key, value] of result.entries()) merged.set(key, value);
  return merged;
}


function findAISuspiciousIncompleteCandidate(item, identity, medianPrice) {
  const title = String(item && item.title || '');
  if (findAIListingFormHint(title, identity) !== 'complete_or_unclear') return true;
  if (!findAITargetExplicitlyEmpty(identity) && /\bempty\b/i.test(title)) return true;
  const p = findAIListingTotal(item);
  if (Number.isFinite(medianPrice) && medianPrice > 0 && Number.isFinite(p) && p > 0 && p < medianPrice * 0.42) return true;
  const status = String(item && item._findaiVisualStatus || '');
  const score = Number(item && item._findaiVisualScore);
  if (status === 'possible' || (Number.isFinite(score) && score < 0.76)) return true;
  return false;
}

async function findAIFilterIncompleteVisualListings(items, identity, evidence, env) {
  const list = Array.isArray(items) ? items.slice() : [];
  if (!list.length) return [];
  const prices = list.map(findAIListingTotal).filter(Number.isFinite).filter(x => x > 0).sort((a,b)=>a-b);
  const median = prices.length ? prices[Math.floor(prices.length / 2)] : null;
  const suspicious = list.map((item,index)=>({item,index})).filter(row => findAISuspiciousIncompleteCandidate(row.item, identity, median)).slice(0, 8);
  if (!suspicious.length || !env || !env.AI) return list.filter(item => findAIListingFormHint(item && item.title, identity) === 'complete_or_unclear');
  const checked = await Promise.all(suspicious.map(async row => ({
    index: row.index,
    wrap: await extractFindAIListingFingerprint(row.item, env)
  })));
  const rejected = new Set();
  for (const row of checked) {
    const fp = row.wrap && row.wrap.fingerprint;
    if (fp && findAIFingerprintHardConflict(fp)) rejected.add(row.index);
  }
  return list.filter((item,index) => !rejected.has(index) && findAIListingFormHint(item && item.title, identity) === 'complete_or_unclear');
}

function findAITrustedRetailerTextFallbackCandidates(candidates, identity, evidence, excludeKeys = new Set()) {
  const out = [];
  for (const item of Array.isArray(candidates) ? candidates : []) {
    if (!item || item._retailerLinkOnly || !(Number(item.price) > 0) || !item.url) continue;
    if (!item._webDiscovery && String(item.discoverySource || '').indexOf('web') < 0) continue;
    const key = hybridListingKey(item); if (!key || excludeKeys.has(key)) continue;
    if (findAIListingFormHint(item.title, identity) !== 'complete_or_unclear') continue;
    if (!findAIProductFormatCompatibility(item.title, identity, evidence)) continue;
    if (!findAIVariantTextCompatibility(item.title, identity, evidence, true)) continue;
    const size = findAISizeCompatibility(item.title, identity); if (!size.compatible) continue;
    const concentration = findAIConcentrationCompatibility(item.title, identity); if (!concentration.compatible) continue;
    const scored = findAIListingScore(item, identity, [identity && identity.canonicalQuery].filter(Boolean));
    // Trusted direct retailer pages can survive without a fetchable thumbnail, but the
    // textual identity must be strong. This is intentionally stricter than normal search.
    if (scored.queryCoverage < 0.46 && scored.requiredCoverage < 0.56) continue;
    out.push({
      ...item,
      _findaiMatchMethod: 'retailer-text',
      _findaiMatchScore: Math.min(0.91, 0.74 + Math.max(scored.queryCoverage, scored.requiredCoverage) * 0.16),
      _findaiVisualStatus: item.image ? 'not-run' : 'image-unavailable',
      _findaiVisualScore: null,
      _findaiVisualForm: 'complete_product',
      _findaiVisualReason: 'Direct priced retailer product page matches the identified product'
    });
  }
  out.sort((a,b)=>findAIListingTotal(a)-findAIListingTotal(b));
  return out.slice(0, 8);
}

async function qualifyAndVerifyFindAIListings(items, identity, queries, evidence, env, originalBytes, country = '') {
  const semantic = prepareFindAIListingCandidates(items, identity, queries);
  if (!semantic.length) return [];
  const selected = selectFindAIVisualCandidates(semantic, FINDAI_VISUAL_CANDIDATE_LIMIT);
  const topSemanticScore = Math.max(...semantic.map(item => Number(item._findaiScore) || 0));
  const comparisons = selected.length
    ? await compareFindAIDirectImagesBatched(originalBytes, selected, identity, evidence, env)
    : new Map();

  let visuallyAccepted = selected.map((item, index) => {
    const check = comparisons.get(String(index)) || { status: 'unverified', score: null, form: 'unclear', reason: 'Direct visual comparison unavailable' };
    return {
      ...item,
      _findaiMatchMethod: 'visual',
      _findaiMatchScore: check.score,
      _findaiVisualStatus: check.status,
      _findaiVisualScore: check.score,
      _findaiVisualForm: check.form,
      _findaiVisualReason: check.reason
    };
  }).filter(item => findAIVisualAccepted(
    { status: item._findaiVisualStatus, score: item._findaiVisualScore, form: item._findaiVisualForm },
    item,
    topSemanticScore
  ));

  // Second completeness pass for visually deceptive results. Empty perfume bottles and
  // empty collectible boxes can look almost identical to the complete product. Low-price
  // outliers / weak visual matches get a dedicated image fingerprint/OCR check before they
  // are allowed to influence Lowest, Average or the listing grid.
  visuallyAccepted = await findAIFilterIncompleteVisualListings(visuallyAccepted, identity, evidence, env);

  const acceptedKeys = new Set(visuallyAccepted.map(hybridListingKey));
  const exactFallback = findAIExactTextFallbackCandidates(semantic, identity, evidence, acceptedKeys);
  exactFallback.forEach(item => acceptedKeys.add(hybridListingKey(item)));
  // Direct retailer pages often block thumbnails. Let a strongly matching, priced retailer
  // page survive without pixels rather than letting eBay monopolise the scan result.
  const retailerFallback = findAITrustedRetailerTextFallbackCandidates(semantic, identity, evidence, acceptedKeys);
  let combined = [...visuallyAccepted, ...exactFallback, ...retailerFallback].slice(0, 24);
  combined = await findAIFilterIncompleteVisualListings(combined, identity, evidence, env);

  // Exactness has already been enforced. Now use the same regional/category authority
  // graph as typed FindAI search, so StockX/official/major retailers are not undone by
  // a final cheapest-eBay sort. Price is only a later tie-breaker inside authority bands.
  const q=String((Array.isArray(queries)&&queries[0])||identity&&identity.canonicalQuery||'').trim();
  if(q){
    const intent=parseSearchIntent(q);
    combined=findAIRankMergedResults(combined,intent,q,country,24);
  }else combined.sort((a,b)=>(Number(b._findaiMatchScore)||0)-(Number(a._findaiMatchScore)||0)||findAIListingTotal(a)-findAIListingTotal(b));
  return combined.slice(0,12);
}

function findAIMarketData(listings) {
  const first = Array.isArray(listings) && listings[0];
  const currency = String(first && first.currency || 'USD');
  let prices = (Array.isArray(listings) ? listings : []).filter(item => String(item.currency || currency) === currency).map(findAIListingTotal).filter(Number.isFinite).sort((a, b) => a - b);
  if (!prices.length) return { lowest: null, average: null, median: null, listingCount: 0, currency };
  const median = prices[Math.floor(prices.length / 2)];
  const sensible = prices.filter(p => prices.length < 5 || (p >= median * 0.35 && p <= median * 3));
  if (sensible.length >= 3) prices = sensible;
  const trim = prices.length >= 10 ? Math.floor(prices.length * 0.1) : 0;
  const averageSet = trim ? prices.slice(trim, prices.length - trim) : prices;
  const average = averageSet.reduce((sum, p) => sum + p, 0) / Math.max(1, averageSet.length);
  return { lowest: prices[0], average, median: prices[Math.floor(prices.length / 2)], listingCount: prices.length, currency };
}

async function findAIImageHash(bytes) {
  try {
    const buffer = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes || []);
    const digest = await crypto.subtle.digest('SHA-256', buffer);
    return [...new Uint8Array(digest)].map(b => b.toString(16).padStart(2, '0')).join('');
  } catch (_) { return ''; }
}

const FINDAI_FAST_IDENTITY_PROMPT = `Identify the exact sellable product shown in this one photo. Return one JSON object only:
{"kind":"product|not_product","brand":"","productLine":"","model":"","variant":"","category":"","size":"","productForm":"","visibleText":[],"requiredTerms":[],"negativeTerms":[],"exactQuery":"","confidence":0.0,"needsAnotherAngle":false,"angleRequest":""}
Rules:
- Preserve exact visible product names, set/model numbers, editions, variants, sizes and concentrations.
- Do not reduce a named item to a broad category such as "Pokemon cards", "LEGO Harry Potter" or "Chanel fragrance" when more specific text is visible.
- Do not invent hidden attributes.
- exactQuery should be the shortest precise marketplace query supported by the photo. A visible brand + named product line is enough even when the hidden size/variant is unknown.
- For fragrance preserve the named line/flanker; for trading cards preserve the expansion/set name plus booster box/ETB/other visible format.
- productForm must describe the complete photographed object, such as elite trainer box, fragrance bottle, assembled LEGO set, handbag, shoe, phone or game console.
- Use one fast best answer. Do not mention eBay.`;

async function identifyFindAIProductFast(bytes, env, independentFallback = false) {
  const wrap = await runFindAIVisionJson(bytes, FINDAI_FAST_IDENTITY_PROMPT, env, 560, independentFallback ? VISION_MODEL : FINDAI_PRIMARY_VISION_MODEL);
  const raw = wrap && wrap.data && typeof wrap.data === 'object' ? wrap.data : null;
  if (!raw) return { identity: null, evidence: null, errors: [String(wrap && wrap.error || 'Fast identity unavailable')] };
  const confidenceRaw = Number(raw.confidence);
  const identity = enrichFindAIIdentity({
    kind: String(raw.kind || 'product').toLowerCase(),
    brand: String(raw.brand || '').trim(),
    productLine: String(raw.productLine || '').trim(),
    model: String(raw.model || '').trim(),
    variant: String(raw.variant || '').trim(),
    category: String(raw.category || '').trim(),
    size: String(raw.size || '').trim(),
    visibleText: normaliseFindAIArray(raw.visibleText, 24),
    visualFeatures: [],
    canonicalQuery: String(raw.exactQuery || [raw.brand, raw.productLine, raw.model, raw.variant, raw.size].filter(Boolean).join(' ')).replace(/\s+/g, ' ').trim(),
    queryVariants: [],
    requiredTerms: normaliseFindAIArray(raw.requiredTerms, 12),
    negativeTerms: normaliseFindAIArray(raw.negativeTerms, 12),
    confidence: Number.isFinite(confidenceRaw) ? Math.max(0, Math.min(1, confidenceRaw > 1 ? confidenceRaw / 100 : confidenceRaw)) : null,
    needsAnotherAngle: raw.needsAnotherAngle === true,
    angleRequest: String(raw.angleRequest || '').trim(),
    reason: ''
  }, {
    productForm: String(raw.productForm || '').trim(),
    primaryObject: String(raw.productForm || '').trim(),
    visibleText: normaliseFindAIArray(raw.visibleText, 24),
    clearlyNot: []
  });
  return {
    identity,
    evidence: {
      productForm: String(raw.productForm || '').trim(),
      primaryObject: String(raw.productForm || '').trim(),
      visibleText: normaliseFindAIArray(raw.visibleText, 24),
      clearlyNot: []
    },
    errors: wrap && wrap.error ? [String(wrap.error)] : []
  };
}

function findAIFallbackIdentityFromImageResults(items) {
  const first = Array.isArray(items) ? items.find(item => item && item.title) : null;
  if (!first) return { identity: null, evidence: null };
  const title = String(first.title || '').replace(/\s+/g, ' ').trim();
  const brand = String(first.brand || '').trim();
  return {
    identity: {
      kind: 'product', brand, productLine: '', model: '', variant: '',
      category: String(first.categoryName || '').trim(), size: '', visibleText: [], visualFeatures: [],
      canonicalQuery: title, queryVariants: [title], requiredTerms: [], negativeTerms: [],
      confidence: 0.62, needsAnotherAngle: false, angleRequest: '', reason: 'Identity derived from eBay visual candidates'
    },
    evidence: {
      productForm: String(first.categoryName || '').trim(),
      primaryObject: String(first.categoryName || '').trim(),
      visibleText: [], clearlyNot: []
    }
  };
}

function findAIImageCandidateConflict(item, identity, evidence) {
  if (!item || !item.title || !(Number(item.price) > 0) || !item.image) return true;
  const formHint = findAIListingFormHint(item.title, identity);
  if (formHint !== 'complete_or_unclear') return true;
  if (!findAIProductFormatCompatibility(item.title, identity, evidence)) return true;
  const size = findAISizeCompatibility(item.title, identity);
  if (!size.compatible) return true;
  const concentration = findAIConcentrationCompatibility(item.title, identity);
  if (!concentration.compatible) return true;
  return false;
}

function qualifyFastEbayImageMatches(items, identity, evidence) {
  const source = Array.isArray(items) ? items : [];
  const seen = new Set();
  const specificity = findAIIdentitySpecificity(identity, evidence);
  const queries = [identity && identity.canonicalQuery].filter(Boolean);
  const candidates = [];
  for (let index = 0; index < source.length; index++) {
    const item = source[index];
    const key = hybridListingKey(item);
    if (!key || seen.has(key) || findAIImageCandidateConflict(item, identity, evidence)) continue;
    seen.add(key);
    const rank = Number.isFinite(Number(item._visualRank)) ? Number(item._visualRank) : index;
    const scored = findAIListingScore(item, identity, queries);
    const exact = specificity.specific ? findAIExactTextMatch(item, identity, evidence) : null;
    const visuallyElite = rank < 3;
    const visuallyStrong = rank < 14 && (scored.queryCoverage >= 0.18 || scored.requiredCoverage >= 0.34 || !specificity.specific);
    const visuallyBroad = rank < 35 && !!exact;
    if (!(visuallyElite || visuallyStrong || visuallyBroad)) continue;
    const visualWeight = Math.max(0, 120 - rank * 4.2);
    const combinedScore = visualWeight + Math.max(-40, scored.score) * 0.58 + (exact ? 62 : 0);
    candidates.push({
      ...item,
      _visualMatch: true,
      _findaiMatchMethod: 'ebay-image',
      _findaiMatchScore: exact ? exact.confidence : null,
      _findaiVisualStatus: 'ebay-image-match',
      _findaiVisualScore: null,
      _findaiVisualForm: 'complete_product',
      _findaiVisualReason: 'Retrieved by eBay Browse visual search and screened by FindAI product-form checks',
      _findaiScore: combinedScore,
      totalPrice: findAIListingTotal(item)
    });
  }
  // Keep only the strongest relevance band before price sorting. This prevents a
  // cheap but weak visual result from becoming the lead card.
  candidates.sort((a, b) => (b._findaiScore || 0) - (a._findaiScore || 0));
  if (!candidates.length) return [];
  const topScore = Number(candidates[0]._findaiScore) || 0;
  let strong = candidates.filter(item => Number(item._findaiScore) >= topScore - 46);
  if (strong.length < 4) strong = candidates.slice(0, Math.min(8, candidates.length));
  strong = strong.slice(0, 18);
  strong.sort((a, b) => {
    const pa = findAIListingTotal(a), pb = findAIListingTotal(b);
    if (pa !== pb) return pa - pb;
    return (Number(a._visualRank) || 0) - (Number(b._visualRank) || 0);
  });
  return strong.slice(0, 12);
}

function qualifyFastKeywordFallback(items, identity, evidence) {
  const exact = findAIExactTextFallbackCandidates(
    prepareFindAIListingCandidates(items, identity, [identity && identity.canonicalQuery].filter(Boolean)),
    identity,
    evidence,
    new Set()
  );
  return exact.map(item => ({ ...item, _visualMatch: false })).sort((a, b) => findAIListingTotal(a) - findAIListingTotal(b)).slice(0, 12);
}

function findAIValidBarcodeHint(value) {
  const digits = String(value || '').replace(/\D/g, '');
  if (![8, 12, 13, 14].includes(digits.length)) return '';
  // GTIN check digit: working from the right (excluding the check digit),
  // weights alternate 3,1. This rejects random serial numbers/QR payloads.
  let sum = 0;
  let weight = 3;
  for (let i = digits.length - 2; i >= 0; i--) {
    sum += Number(digits[i]) * weight;
    weight = weight === 3 ? 1 : 3;
  }
  const expected = (10 - (sum % 10)) % 10;
  return expected === Number(digits[digits.length - 1]) ? digits : '';
}

function findAIScanResultKey(item) {
  const host = webDiscoveryHostName(item && item.url || '');
  const id = String(item && (item.itemId || item.marketplaceListingId) || '').trim();
  if (id) return `${String(item && item.source || '').toLowerCase()}:${id}`;
  return `${host}|${hybridNormalise(item && item.title || '')}|${Number(item && item.price) || 0}`;
}

function mergeFindAIScanPools(...pools) {
  const out = [];
  const seen = new Set();
  for (const pool of pools) {
    for (const item of Array.isArray(pool) ? pool : []) {
      if (!item || !item.title || !(Number(item.price) > 0)) continue;
      const key = findAIScanResultKey(item);
      if (!key || seen.has(key)) continue;
      seen.add(key);
      out.push(item);
    }
  }
  return out;
}

function findAIScanSourceKey(item) {
  const host = webDiscoveryHostName(item && item.url || '');
  if (host) return host;
  return hybridNormalise(item && (item.retailer || item.source) || 'unknown') || 'unknown';
}

function findAIScanDiversifyListings(items, limit = 12, query = '', country = '') {
  const raw = [...(Array.isArray(items) ? items : [])].filter(Boolean);
  let sorted;
  if (String(query || '').trim()) {
    // Visual search now uses the SAME v48 authority graph as typed shopping search.
    // Exactness is already enforced before this point; this step decides which valid
    // sources deserve prominence (e.g. StockX/official/major retailer vs four eBay cards).
    const intent = parseSearchIntent(String(query));
    sorted = findAIRankMergedResults(raw, intent, String(query), country, Math.max(limit * 4, 40));
  } else {
    sorted = raw.sort((a, b) => {
      const pa = findAIListingTotal(a), pb = findAIListingTotal(b);
      if (pa !== pb) return pa - pb;
      const rank = method => method === 'visual' ? 3 : method === 'retailer-text' ? 2 : method === 'exact-text' ? 1 : 0;
      const ra = rank(a && a._findaiMatchMethod), rb = rank(b && b._findaiMatchMethod);
      if (ra !== rb) return rb - ra;
      return (Number(b && b._findaiMatchScore) || 0) - (Number(a && a._findaiMatchScore) || 0);
    });
  }
  const chosen = [], chosenKeys = new Set(), sourceCounts = new Map();
  const add = (item, cap) => {
    const source = findAIScanSourceKey(item), key = findAIScanResultKey(item);
    if (!source || !key || chosenKeys.has(key)) return false;
    const used = sourceCounts.get(source) || 0;
    if (used >= cap) return false;
    chosen.push(item); chosenKeys.add(key); sourceCounts.set(source, used + 1);
    return true;
  };
  // Preserve authority order while ensuring one source cannot own the whole first screen.
  for (const item of sorted) { add(item, 1); if (chosen.length >= limit) return chosen; }
  for (const item of sorted) { add(item, 2); if (chosen.length >= limit) return chosen; }
  for (const item of sorted) { add(item, 3); if (chosen.length >= limit) return chosen; }
  return chosen;
}

async function findAIUniversalScanSearch(query, country, env) {
  const clean = String(query || '').replace(/\s+/g, ' ').trim();
  if (!clean) return { items: [], meta: {}, correctedQuery: '' };
  const parsedIntent = parseSearchIntent(clean);
  const effectiveQuery = String(parsedIntent.keywords || clean).trim();
  const webPromise = parsedIntent.source
    ? Promise.resolve({ items: [], correctedQuery: effectiveQuery, status: 'source_locked', cached: false })
    : discoverWebProducts(effectiveQuery, country, env, { deepResolve: true });
  const specialistPromise = findAIFetchSpecialistResults(effectiveQuery, parsedIntent, country, env, null);
  const [coreSearch, webDiscovery, specialistItems] = await Promise.all([
    searchListings(clean, '', country, env),
    webPromise,
    specialistPromise
  ]);
  const coreItems = Array.isArray(coreSearch && coreSearch.items) ? coreSearch.items : [];
  const correctedQuery = String(webDiscovery && webDiscovery.correctedQuery || effectiveQuery || clean).trim();
  let findaiListings = [];
  try { findaiListings = await mpSearchPublicListings(env, correctedQuery, 12, 0); } catch (_) {}
  let merged = mpMergeIntoMarketplaceResults(coreItems, findaiListings, 120);
  merged = mergeWebDiscoveryResults(
    merged,
    [].concat(webDiscovery && webDiscovery.items || [], specialistItems || []),
    coreSearch && coreSearch.meta && coreSearch.meta.shoppingIntent || parsedIntent,
    120,
    correctedQuery || clean,
    country
  );
  return {
    items: merged,
    correctedQuery,
    meta: {
      ...(coreSearch && coreSearch.meta || {}),
      webDiscoveryCount: Array.isArray(webDiscovery && webDiscovery.items) ? webDiscovery.items.length : 0,
      webDiscoveryStatus: String(webDiscovery && webDiscovery.status || 'disabled'),
      webDiscoveryDeepResolve: true,
      webDiscoveryCached: !!(webDiscovery && webDiscovery.cached),
      webDiscoveryBraveCalls: 0,
      webIndexCount: Number(webDiscovery && webDiscovery.webIndexCount || 0),
      webIndexKnownRetailers: Number(webDiscovery && webDiscovery.webIndexKnownRetailers || 0),
      specialistCount: Array.isArray(specialistItems) ? specialistItems.length : 0,
      findaiMarketplaceCount: findaiListings.length,
      correctedQuery
    }
  };
}


function findAIScanIdentitySignature(identity, barcode = '') {
  const stable = [
    barcode || '', identity && identity.brand || '', identity && identity.productLine || '', identity && identity.model || '',
    identity && identity.variant || '', identity && identity.size || '', identity && identity.canonicalQuery || ''
  ].map(hybridNormalise).filter(Boolean).join('|');
  return stable || hybridNormalise(identity && identity.canonicalQuery || '');
}

async function findAIScanReadKnownOffers(identity, barcode, country, env) {
  if (!env || !env.DB || !webIndexEnabled(env)) return { items: [], productKey: '', scanProductKey: '', hit: false };
  try {
    await ensureWebDiscoverySchema(env);
    const signature = findAIScanIdentitySignature(identity, barcode);
    if (!signature) return { items: [], productKey: '', scanProductKey: '', hit: false };
    const row = await env.DB.prepare(`SELECT scan_product_key,web_product_key,canonical_query FROM findai_scan_products WHERE identity_signature=? OR (?<>'' AND barcode=?) ORDER BY last_seen_at DESC LIMIT 1`)
      .bind(signature, String(barcode||''), String(barcode||'')).first();
    if (!row || !row.web_product_key) return { items: [], productKey: '', scanProductKey: '', hit: false };
    const query = String(row.canonical_query || identity && identity.canonicalQuery || '');
    // Refresh a few known retailer URLs directly. This consumes no Brave discovery call.
    await webIndexRefreshKnownOffers(query, country, env, String(row.web_product_key), 8).catch(()=>0);
    const known = await webIndexReadOffers(query, country, env, String(row.web_product_key), 30);
    return { items: Array.isArray(known && known.items) ? known.items : [], productKey: String(row.web_product_key), scanProductKey: String(row.scan_product_key||''), hit: true };
  } catch (_) { return { items: [], productKey: '', scanProductKey: '', hit: false }; }
}

async function findAIScanPersistKnowledge({ identity, evidence, barcode, imageHash, country, query, queryVariants, listings, env, preferredProductKey = '' }) {
  if (!env || !env.DB || !webIndexEnabled(env) || !identity || !query) return { stored: false, retailerOffersStored: 0, productKey: '' };
  try {
    await ensureWebDiscoverySchema(env);
    const product = preferredProductKey ? { productKey: preferredProductKey } : await webIndexEnsureProduct(query, country, env);
    const productKey = String(product && product.productKey || '');
    if (!productKey) return { stored: false, retailerOffersStored: 0, productKey: '' };
    const now = Date.now();
    const signature = findAIScanIdentitySignature(identity, barcode);
    const scanProductKey = 'scan_' + webIndexDurableHash(signature || query);
    const confidence = Number(identity && identity.confidence);
    await env.DB.prepare(`INSERT INTO findai_scan_products(scan_product_key,web_product_key,identity_signature,canonical_query,brand,product_line,model,variant,size,barcode,identity_json,evidence_json,confidence,first_seen_at,last_seen_at,scan_count,last_market_country)
      VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
      ON CONFLICT(scan_product_key) DO UPDATE SET web_product_key=excluded.web_product_key,canonical_query=excluded.canonical_query,brand=CASE WHEN length(excluded.brand)>0 THEN excluded.brand ELSE findai_scan_products.brand END,product_line=CASE WHEN length(excluded.product_line)>0 THEN excluded.product_line ELSE findai_scan_products.product_line END,model=CASE WHEN length(excluded.model)>0 THEN excluded.model ELSE findai_scan_products.model END,variant=CASE WHEN length(excluded.variant)>0 THEN excluded.variant ELSE findai_scan_products.variant END,size=CASE WHEN length(excluded.size)>0 THEN excluded.size ELSE findai_scan_products.size END,barcode=CASE WHEN length(excluded.barcode)>0 THEN excluded.barcode ELSE findai_scan_products.barcode END,identity_json=excluded.identity_json,evidence_json=excluded.evidence_json,confidence=MAX(findai_scan_products.confidence,excluded.confidence),last_seen_at=excluded.last_seen_at,scan_count=findai_scan_products.scan_count+1,last_market_country=excluded.last_market_country`)
      .bind(scanProductKey,productKey,signature,String(query).slice(0,220),String(identity.brand||'').slice(0,100),String(identity.productLine||'').slice(0,140),String(identity.model||'').slice(0,120),String(identity.variant||'').slice(0,160),String(identity.size||'').slice(0,80),String(barcode||'').slice(0,32),JSON.stringify({...identity,_scannerVersion:FINDAI_SCAN_VERSION}).slice(0,12000),JSON.stringify(evidence||{}).slice(0,12000),Number.isFinite(confidence)?confidence:0,now,now,1,webDiscoveryCountry(country)).run();
    if (imageHash) {
      await env.DB.prepare(`INSERT INTO findai_scan_observations(image_hash,scan_product_key,market_country,confidence,observed_at) VALUES(?,?,?,?,?) ON CONFLICT(image_hash) DO UPDATE SET scan_product_key=excluded.scan_product_key,market_country=excluded.market_country,confidence=MAX(findai_scan_observations.confidence,excluded.confidence),observed_at=excluded.observed_at`)
        .bind(String(imageHash),scanProductKey,webDiscoveryCountry(country),Number.isFinite(confidence)?confidence:0,now).run();
    }
    const aliases = [query, ...(Array.isArray(queryVariants)?queryVariants:[]), barcode].filter(Boolean);
    for (const alias of aliases.slice(0,8)) await webIndexBindAlias(String(alias), country, productKey, env, now).catch(()=>{});
    // Only persist direct web-retailer offers here. Marketplace APIs remain live sources;
    // retailer URLs/prices become FindAI-owned reusable index knowledge.
    const retailerOffers = (Array.isArray(listings)?listings:[]).filter(item => item && item._webDiscovery && !item._retailerLinkOnly && Number(item.price)>0);
    const upsert = retailerOffers.length ? await webIndexUpsertItems(query, country, retailerOffers, env, productKey) : { stored: 0 };
    return { stored: true, retailerOffersStored: Number(upsert && upsert.stored)||0, productKey, scanProductKey };
  } catch (_) { return { stored: false, retailerOffersStored: 0, productKey: '' }; }
}


const FINDAI_SCAN_CONTINUATION_TTL_MS = 5 * 60 * 1000;

function findAICompactEvidence(evidence) {
  const e = evidence && typeof evidence === 'object' ? evidence : {};
  return {
    visibleText: normaliseFindAIArray(e.visibleText, 30),
    logos: normaliseFindAIArray(e.logos, 16),
    modelNumbers: normaliseFindAIArray(e.modelNumbers, 16),
    distinctiveFeatures: normaliseFindAIArray(e.distinctiveFeatures, 16),
    primaryObject: String(e.primaryObject || '').slice(0, 180),
    productForm: String(e.productForm || '').slice(0, 180),
    category: String(e.category || '').slice(0, 120),
    colour: String(e.colour || e.color || '').slice(0, 100)
  };
}

async function issueFindAIScanContinuation(env, payload) {
  const body = JSON.stringify({
    v: 1,
    x: Date.now() + FINDAI_SCAN_CONTINUATION_TTL_MS,
    h: String(payload && payload.imageHash || ''),
    c: webDiscoveryCountry(payload && payload.country),
    b: String(payload && payload.barcode || ''),
    i: payload && payload.identity || {},
    e: findAICompactEvidence(payload && payload.evidence),
    q: Array.isArray(payload && payload.queries) ? payload.queries.slice(0, 6) : []
  });
  const p64 = b64urlEncode(new TextEncoder().encode(body));
  const key = await sessionHmacKey(env);
  const sig = new Uint8Array(await crypto.subtle.sign('HMAC', key, new TextEncoder().encode('scan:' + p64)));
  return p64 + '.' + b64urlEncode(sig);
}

async function verifyFindAIScanContinuation(env, token, imageHash, country) {
  try {
    const parts = String(token || '').split('.');
    if (parts.length !== 2) return null;
    const [p64, s64] = parts;
    const key = await sessionHmacKey(env);
    const expect = new Uint8Array(await crypto.subtle.sign('HMAC', key, new TextEncoder().encode('scan:' + p64)));
    if (b64urlEncode(expect) !== s64) return null;
    const data = JSON.parse(b64urlDecodeToString(p64));
    if (!data || Number(data.x) < Date.now()) return null;
    if (String(data.h || '') !== String(imageHash || '')) return null;
    if (webDiscoveryCountry(data.c) !== webDiscoveryCountry(country)) return null;
    return data;
  } catch (_) { return null; }
}

async function findAIScanRecallObservation(imageHash, country, env) {
  if (!imageHash || !env || !env.DB || !webIndexEnabled(env)) return null;
  try {
    await ensureWebDiscoverySchema(env);
    const row = await env.DB.prepare(`SELECT p.* FROM findai_scan_observations o JOIN findai_scan_products p ON p.scan_product_key=o.scan_product_key WHERE o.image_hash=? ORDER BY o.observed_at DESC LIMIT 1`).bind(String(imageHash)).first();
    if (!row) return null;
    let identity = {}, evidence = {};
    try { identity = JSON.parse(String(row.identity_json || '{}')); } catch (_) {}
    if (String(identity && identity._scannerVersion || '') !== FINDAI_SCAN_VERSION) return null;
    try { evidence = JSON.parse(String(row.evidence_json || '{}')); } catch (_) {}
    const quality = findAIIdentityQuality(identity, evidence, row.barcode || '');
    if (!quality.valid) return null;
    return { identity, evidence, quality, barcode: String(row.barcode || ''), productKey: String(row.web_product_key || ''), scanProductKey: String(row.scan_product_key || ''), canonicalQuery: String(row.canonical_query || '') };
  } catch (_) { return null; }
}

async function findAIScanReadCachedOffers(identity, barcode, country, env, query = '') {
  if (!env || !env.DB || !webIndexEnabled(env)) return { items: [], productKey: '', scanProductKey: '', hit: false };
  try {
    await ensureWebDiscoverySchema(env);
    const signature = findAIScanIdentitySignature(identity, barcode);
    let row = signature ? await env.DB.prepare(`SELECT scan_product_key,web_product_key,canonical_query FROM findai_scan_products WHERE identity_signature=? OR (?<>'' AND barcode=?) ORDER BY last_seen_at DESC LIMIT 1`)
      .bind(signature, String(barcode || ''), String(barcode || '')).first() : null;
    let productKey = String(row && row.web_product_key || '');
    const canonicalQuery = String(row && row.canonical_query || query || identity && identity.canonicalQuery || '').trim();
    if (!productKey && canonicalQuery) {
      const product = await webIndexEnsureProduct(canonicalQuery, country, env);
      productKey = String(product && product.productKey || '');
    }
    if (!productKey) return { items: [], productKey: '', scanProductKey: '', hit: false };
    const known = await webIndexReadOffers(canonicalQuery || query, country, env, productKey, 30);
    return { items: Array.isArray(known && known.items) ? known.items : [], productKey, scanProductKey: String(row && row.scan_product_key || ''), hit: !!(row || (known && known.items && known.items.length)), knownRetailers: Number(known && known.knownRetailers || 0) };
  } catch (_) { return { items: [], productKey: '', scanProductKey: '', hit: false }; }
}

async function findAIFastIdentityRetrieval(query, country, env) {
  const clean = String(query || '').replace(/\s+/g, ' ').trim();
  if (!clean) return { items: [], meta: {}, correctedQuery: '' };
  const parsed = parseSearchIntent(clean);
  const effective = String(parsed.keywords || clean).trim();
  const [core, specialist] = await Promise.all([
    promiseWithin(searchListings(clean, '', country, env), 5000, { items: [], meta: {} }),
    promiseWithin(findAIFetchSpecialistResults(effective, parsed, country, env, null), 4200, [])
  ]);
  let productKey = '';
  try { const product = await webIndexEnsureProduct(effective, country, env); productKey = String(product && product.productKey || ''); } catch (_) {}
  const cached = productKey ? await webIndexReadOffers(effective, country, env, productKey, 20).catch(()=>({items:[]})) : { items: [] };
  let merged = mergeFindAIScanPools(cached && cached.items, core && core.items, specialist);
  return { items: merged, correctedQuery: effective, meta: { ...(core && core.meta || {}), webIndexProductKey: productKey, fastIdentityRetrieval: true } };
}

async function findAIScanQuickOfferSearch(query, identity, evidence, barcode, country, env) {
  const clean = String(query || '').replace(/\s+/g, ' ').trim();
  if (!clean && !barcode) return { items: [], rawItems: [], productKey: '', meta: {} };
  const parsed = parseSearchIntent(clean || barcode);
  const effective = String(parsed.keywords || clean || barcode).trim();
  // Fast lane: marketplace APIs + FindAI's existing D1 index only. Never wait for Brave
  // or rendered retailer crawling before putting useful listings on the results screen.
  const corePromise = clean
    ? promiseWithin(searchListings(clean, '', country, env), 4200, { items: [], meta: {}, error: 'Quick marketplace search timed out' })
    : Promise.resolve({ items: [], meta: {} });
  const specialistPromise = effective
    ? promiseWithin(findAIFetchSpecialistResults(effective, parsed, country, env, null), 2800, [])
    : Promise.resolve([]);
  let productKey = '';
  const indexPromise = (async () => {
    if (!effective || !env || !env.DB || !webIndexEnabled(env)) return { items: [] };
    try {
      const product = await webIndexEnsureProduct(effective, country, env);
      productKey = String(product && product.productKey || '');
      return productKey ? await webIndexReadOffers(effective, country, env, productKey, 24) : { items: [] };
    } catch (_) { return { items: [] }; }
  })();
  const barcodePromise = barcode
    ? promiseWithin(searchListings(barcode, '', country, env), 3200, { items: [], meta: {} })
    : Promise.resolve({ items: [], meta: {} });
  const [core, specialist, indexed, barcodeSearch] = await Promise.all([corePromise, specialistPromise, indexPromise, barcodePromise]);
  const rawItems = mergeFindAIScanPools(indexed && indexed.items, core && core.items, specialist, barcodeSearch && barcodeSearch.items);
  const items = qualifyFindAICachedListings(rawItems, identity, [clean || effective].filter(Boolean), evidence, country);
  return { items, rawItems, productKey, meta: { ...(core && core.meta || {}), quickOfferSearch: true, quickRawCount: rawItems.length, quickQualifiedCount: items.length } };
}

async function findAIScanDeepOfferSearch(queryCandidates, identity, evidence, barcode, country, env) {
  const queries = (Array.isArray(queryCandidates) ? queryCandidates : []).map(x => String(x || '').replace(/\s+/g,' ').trim()).filter(Boolean);
  const primary = queries[0] || String(identity && identity.canonicalQuery || '').trim() || String(barcode || '');
  const alternate = queries.find(q => hybridNormalise(q) !== hybridNormalise(primary)) || '';
  if (!primary) return { candidatePool: [], primaryQuery: '', metas: [], knownScan: {items:[],hit:false}, webDiscovery: {}, searchQueries: [] };
  const parsed = parseSearchIntent(primary);
  const effective = String(parsed.keywords || primary).trim();

  // Every lane has its own timeout. A slow retailer crawl must never erase fast eBay,
  // marketplace, D1 or specialist results as happened in v46 when the whole aggregate
  // search was wrapped in one timeout.
  const knownPromise = promiseWithin(findAIScanReadKnownOffers(identity, barcode, country, env), 6500, {items:[],productKey:'',scanProductKey:'',hit:false});
  const corePrimaryPromise = promiseWithin(searchListings(primary, '', country, env), 6500, {items:[],meta:{},error:'Primary marketplace lane timed out'});
  const coreAlternatePromise = alternate
    ? promiseWithin(searchListings(alternate, '', country, env), 5500, {items:[],meta:{},error:'Alternate marketplace lane timed out'})
    : Promise.resolve({items:[],meta:{}});
  const specialistPromise = promiseWithin(findAIFetchSpecialistResults(effective, parsed, country, env, null), 5000, []);
  const barcodePromise = barcode
    ? promiseWithin(searchListings(barcode, '', country, env), 5000, {items:[],meta:{}})
    : Promise.resolve({items:[],meta:{}});
  const findaiMarketplacePromise = promiseWithin(mpSearchPublicListings(env, effective, 16, 0), 3500, []);
  const directIndexPromise = (async () => {
    if (!env || !env.DB || !webIndexEnabled(env)) return {items:[],productKey:''};
    try {
      const product = await webIndexEnsureProduct(effective, country, env);
      const productKey = String(product && product.productKey || '');
      const indexed = productKey ? await webIndexReadOffers(effective, country, env, productKey, 40) : {items:[]};
      return {items:Array.isArray(indexed&&indexed.items)?indexed.items:[],productKey};
    } catch (_) { return {items:[],productKey:''}; }
  })();
  const webPromise = parsed.source
    ? Promise.resolve({items:[],correctedQuery:effective,status:'source_locked',cached:false})
    : promiseWithin(discoverWebProducts(effective, country, env, { deepResolve: true }), 17000, {items:[],correctedQuery:effective,status:'timeout',cached:false,error:'Retailer discovery timed out'});

  const [knownScan, corePrimary, coreAlternate, specialist, barcodeSearch, findaiListings, directIndex, webDiscovery] = await Promise.all([
    knownPromise, corePrimaryPromise, coreAlternatePromise, specialistPromise, barcodePromise, findaiMarketplacePromise, directIndexPromise, webPromise
  ]);
  const corrected = String(webDiscovery && webDiscovery.correctedQuery || effective || primary).trim();
  let candidatePool = mergeFindAIScanPools(
    knownScan && knownScan.items,
    directIndex && directIndex.items,
    corePrimary && corePrimary.items,
    coreAlternate && coreAlternate.items,
    specialist,
    barcodeSearch && barcodeSearch.items,
    findaiListings,
    webDiscovery && webDiscovery.items
  );
  return {
    candidatePool,
    primaryQuery: corrected || primary,
    knownScan,
    webDiscovery: webDiscovery || {},
    directIndex,
    metas: [corePrimary && corePrimary.meta || {}, coreAlternate && coreAlternate.meta || {}],
    searchQueries: [primary, alternate].filter(Boolean),
    laneCounts: {
      known: Number(knownScan && knownScan.items && knownScan.items.length || 0),
      indexed: Number(directIndex && directIndex.items && directIndex.items.length || 0),
      primaryMarketplace: Number(corePrimary && corePrimary.items && corePrimary.items.length || 0),
      alternateMarketplace: Number(coreAlternate && coreAlternate.items && coreAlternate.items.length || 0),
      specialist: Number(Array.isArray(specialist) ? specialist.length : 0),
      findaiMarketplace: Number(Array.isArray(findaiListings) ? findaiListings.length : 0),
      web: Number(webDiscovery && webDiscovery.items && webDiscovery.items.length || 0)
    }
  };
}

function qualifyFindAICachedListings(items, identity, queries, evidence, country = '') {
  const semantic = prepareFindAIListingCandidates(items, identity, queries);
  if (!semantic.length) return [];
  const accepted = [];
  const seen = new Set();
  for (const item of findAITrustedRetailerTextFallbackCandidates(semantic, identity, evidence, seen)) {
    const key = hybridListingKey(item); if (key) seen.add(key); accepted.push(item);
  }
  for (const item of findAIExactTextFallbackCandidates(semantic, identity, evidence, seen)) {
    const key = hybridListingKey(item); if (key) seen.add(key); accepted.push(item);
  }
  return findAIScanDiversifyListings(accepted, 8, (Array.isArray(queries)&&queries[0]) || identity&&identity.canonicalQuery || '', country);
}

function findAIIdentityRefinementQuery(identity,evidence){
  const id=sanitiseFindAIIdentity(identity||{},evidence||{});
  const parts=[id.brand,id.productLine,id.model].filter(Boolean);
  let base=findAIIdentityUniqueParts({brand:parts[0]||'',productLine:parts[1]||'',model:parts[2]||'',variant:'',size:''}).join(' ').replace(/\s+/g,' ').trim();
  // Retrieval should be BROADER than the proposed variant. If the first vision pass calls
  // a Zebra "Triple Black", searching only Triple Black can never surface Zebra images to
  // correct the mistake. Search the shared family and let pixel comparison choose release.
  if(hybridTokens(base,true).length<2)base=String(id.canonicalQuery||'').trim();
  return base;
}

async function resolveFindAIScanIdentityFast({ bytes, contextBytes, country, userMsg, barcodeHint, env }) {
  const barcode = findAIValidBarcodeHint(barcodeHint);
  const imageHash = await findAIImageHash(bytes);
  const recalled = await findAIScanRecallObservation(imageHash, country, env);
  if (recalled) {
    let identity = barcode ? { ...recalled.identity, barcode } : recalled.identity;
    const evidence = recalled.evidence || {};
    let quality = recalled.quality || findAIIdentityQuality(identity, evidence, barcode || recalled.barcode || '');
    let variantRefined = false;
    // Old scan memory may contain a correct base model but not the exact release. Re-run
    // only the lightweight retrieval resolver when v13 detects that missing specificity.
    if (!barcode && quality && quality.valid && findAIIdentityNeedsRetrievalRefinement(identity, evidence)) {
      const refineQuery = findAIIdentityRefinementQuery(identity,evidence);
      if (refineQuery) {
        const variantSearch = await promiseWithin(findAIFastIdentityRetrieval(refineQuery, country, env), 4200, {items:[]});
        if (variantSearch && variantSearch.items && variantSearch.items.length) {
          const candidateIdentity = await promiseWithin(refineFindAIIdentityFromVisualCandidates(identity, evidence, variantSearch.items, bytes, env), 11000, identity);
          if (findAIRefinedIdentityIsBetter(identity, candidateIdentity, evidence, quality)) {
            identity = candidateIdentity;
            quality = findAIIdentityQuality(identity, evidence, barcode || recalled.barcode || '');
            variantRefined = true;
          }
        }
      }
    }
    return { imageHash, barcode: barcode || recalled.barcode || '', identity, evidence, quality, errors: [], recalled: true, variantRefined, productKey: recalled.productKey || '', scanProductKey: recalled.scanProductKey || '' };
  }
  let analysis = await promiseWithin(
    identifyFindAIProduct(contextBytes&&contextBytes.length?[bytes,contextBytes]:bytes, env),
    12500,
    { identity: null, evidence: null, quality: null, errors: ['FindAI identity analysis timed out'] }
  );
  if (!analysis || !analysis.identity) analysis = await promiseWithin(
    identifyFindAIProductFast(bytes, env),
    3200,
    { identity: null, evidence: null, quality: null, errors: ['Fast FindAI identity analysis timed out'] }
  );
  let identity = analysis && analysis.identity || { kind:'product', brand:'', productLine:'', model:'', variant:'', category:'', size:'', visibleText:[], canonicalQuery:'', queryVariants:[], requiredTerms:[], negativeTerms:[], confidence:null, needsAnotherAngle:false, angleRequest:'' };
  const evidence = analysis && analysis.evidence || {};
  if (barcode) identity = { ...identity, barcode };
  let quality = findAIIdentityQuality(identity, evidence, barcode);
  const userHint = String(userMsg || '').replace(/\s+/g, ' ').trim().slice(0,120);
  const seeds = findAIEvidenceSeedQueries(evidence, userHint);
  let recoverySearch = null, recoveryQuery = '', variantRefined = false;
  if (!quality.valid && !barcode && seeds.length) {
    recoveryQuery = seeds[0];
    recoverySearch = await findAIFastIdentityRetrieval(recoveryQuery, country, env);
    if (recoverySearch && recoverySearch.items && recoverySearch.items.length) {
      identity = await promiseWithin(refineFindAIIdentityFromCandidates(identity, evidence, recoverySearch.items, env), 4200, identity);
      quality = findAIIdentityQuality(identity, evidence, barcode);
    }
  }

  // A broad-but-valid identity such as "Yeezy Boost 350 V2" should not skip the
  // retrieval-assisted resolver just because the base model is recognisable. For
  // variant-sensitive categories, use one lightweight candidate pass to resolve a
  // visually supported colourway/release/flanker before any live listing search runs.
  // This is category-level behaviour, not a product-specific patch.
  if (quality.valid && !barcode && findAIIdentityNeedsRetrievalRefinement(identity, evidence)) {
    const refineQuery = findAIIdentityRefinementQuery(identity,evidence) || String(seeds[0]||'').trim();
    if (refineQuery) {
      const variantSearch = await promiseWithin(findAIFastIdentityRetrieval(refineQuery, country, env), 4200, {items:[],meta:{},correctedQuery:refineQuery});
      if (variantSearch && variantSearch.items && variantSearch.items.length) {
        const candidateIdentity = await promiseWithin(refineFindAIIdentityFromVisualCandidates(identity, evidence, variantSearch.items, bytes, env), 11000, identity);
        if (findAIRefinedIdentityIsBetter(identity, candidateIdentity, evidence, quality)) {
          identity = candidateIdentity;
          quality = findAIIdentityQuality(identity, evidence, barcode);
          variantRefined = true;
          if (!recoverySearch) recoverySearch = variantSearch;
          if (!recoveryQuery) recoveryQuery = refineQuery;
        }
      }
    }
  }
  return { imageHash, barcode, identity, evidence, quality, errors: analysis && analysis.errors || [], recalled: false, recoverySearch, recoveryQuery, variantRefined, userHint };
}

async function runHybridVisionIdentify({ bytes, contextBytes, country, userMsg, barcodeHint, env }) {
  const startedAt = Date.now();
  const resolved = await resolveFindAIScanIdentityFast({ bytes, contextBytes, country, userMsg, barcodeHint, env });
  const { imageHash, barcode, evidence } = resolved;
  let identity = resolved.identity || {};
  if (identity.kind === 'not_product' && !barcode) {
    return { reply:'I could not identify a sellable product in that photo. Try filling the frame with one item.', query:'', productName:'', identity, evidence:findAICompactEvidence(evidence), listings:[], items:[], kind:'not_product', needsAnotherAngle:true, angleRequest:identity.angleRequest||'Photograph one product clearly, with the front label or model details visible.', market:{lowest:null,average:null,median:null,listingCount:0,currency:currencyFor(country)}, country, meta:{scanner:FINDAI_SCAN_VERSION,phase:'identify',deepSearchPending:false,independentRecognition:true,elapsedMs:Date.now()-startedAt} };
  }
  if (!resolved.quality || !resolved.quality.valid) {
    return { reply:'I can see a product, but I could not identify it confidently enough to search the exact item.', query:resolved.recoveryQuery||'', productName:'', identity, evidence:findAICompactEvidence(evidence), listings:[], items:[], kind:'unresolved_product', needsAnotherAngle:true, angleRequest:identity.angleRequest||'Photograph the front label, model number or another clear angle.', market:{lowest:null,average:null,median:null,listingCount:0,currency:currencyFor(country)}, country, meta:{scanner:FINDAI_SCAN_VERSION,phase:'identify',deepSearchPending:false,independentRecognition:true,identityQuality:resolved.quality&&resolved.quality.score,elapsedMs:Date.now()-startedAt} };
  }
  const seeds = findAIEvidenceSeedQueries(evidence, resolved.userHint || '');
  const identityQueries = findAIQueryVariants(identity, evidence);
  const canonical = String(identity.canonicalQuery || identityQueries[0] || resolved.recoveryQuery || '').replace(/\s+/g,' ').trim();
  const queryCandidates = [canonical, ...identityQueries, ...seeds, resolved.userHint].filter(Boolean).filter((v,i,a)=>a.findIndex(x=>hybridNormalise(x)===hybridNormalise(v))===i).slice(0,6);
  const primaryQuery = queryCandidates[0] || barcode || '';
  const [cached, quick] = await Promise.all([
    promiseWithin(findAIScanReadCachedOffers(identity, barcode, country, env, primaryQuery), 1800, {items:[],productKey:'',scanProductKey:'',hit:false}),
    promiseWithin(findAIScanQuickOfferSearch(primaryQuery, identity, evidence, barcode, country, env), 4600, {items:[],rawItems:[],productKey:'',meta:{},error:'Quick offer phase timed out'})
  ]);
  const cachedListings = qualifyFindAICachedListings(cached.items, identity, queryCandidates, evidence, country);
  const initialListings = findAIScanDiversifyListings(mergeFindAIScanPools(cachedListings, quick && quick.items), 10, primaryQuery, country);
  const productName = findAIIdentityDisplayName(identity, primaryQuery);
  const token = await issueFindAIScanContinuation(env, { imageHash, country, barcode, identity, evidence, queries: queryCandidates });
  const market = findAIMarketData(initialListings);
  const knowledge = await promiseWithin(findAIScanPersistKnowledge({ identity, evidence, barcode, imageHash, country, query:primaryQuery, queryVariants:queryCandidates, listings:initialListings, env, preferredProductKey:String(cached.productKey||quick&&quick.productKey||resolved.productKey||'') }), 1800, {stored:false});
  return {
    reply:`Looks like you've sent a photo of ${productName}. FindAI is searching live listings and prices across retailers and marketplaces.`, query:primaryQuery, exactQuery:primaryQuery, product:productName, productName, title:productName,
    brand:identity.brand||'', productLine:identity.productLine||'', model:identity.model||'', variant:identity.variant||'', category:identity.category||'', size:identity.size||'', barcode:barcode||'',
    visibleText:identity.visibleText||[], requiredTerms:identity.requiredTerms||[], confidence:identity.confidence, identity, evidence:findAICompactEvidence(evidence),
    listings:initialListings, items:initialListings, market:{...market,totalAvailable:Math.max(Number(cached&&cached.items&&cached.items.length||0),Number(quick&&quick.rawItems&&quick.rawItems.length||0))}, country, kind:'product', scanContinuationToken:token,
    meta:{ scanner:FINDAI_SCAN_VERSION,phase:'identify',deepSearchPending:true,independentRecognition:true,recognitionModels:[FINDAI_PRIMARY_VISION_MODEL,FINDAI_SECONDARY_VISION_MODEL,FINDAI_OCR_VISION_MODEL,...(findAIFrontierVisionEnabled(env)?[FINDAI_FRONTIER_VISION_MODEL]:[])],frontierVisionAttempted:findAIFrontierVisionEnabled(env),ensembleConsensus:Number(identity&&identity._ensembleConsensus)||null,ensembleDisagreement:identity&&identity._ensembleDisagreement===true,recognitionRecalled:!!resolved.recalled,variantRefined:!!resolved.variantRefined,identityQuality:resolved.quality.score,scanKnowledgeHit:!!cached.hit,sourceCount:new Set(initialListings.map(findAIScanSourceKey)).size,quickOfferCount:initialListings.length,quickRawCount:Number(quick&&quick.rawItems&&quick.rawItems.length||0),marketplaceImageSearchUsed:false,independentOfMarketplaceImageRecognition:true,elapsedMs:Date.now()-startedAt,scanKnowledgeStored:!!(knowledge&&knowledge.stored) }
  };
}

async function runHybridVisionExpand({ bytes, country, continuationToken, env }) {
  const startedAt = Date.now();
  const imageHash = await findAIImageHash(bytes);
  const continuation = await verifyFindAIScanContinuation(env, continuationToken, imageHash, country);
  if (!continuation) return { error:'invalid_scan_continuation', reply:'That scan session expired. Retake the photo to refresh it.', listings:[], items:[], kind:'scan_expired', meta:{scanner:FINDAI_SCAN_VERSION,phase:'expand',deepSearchPending:false} };
  const identity = continuation.i || {}, evidence = continuation.e || {}, barcode = String(continuation.b || '');
  const queryCandidates = (Array.isArray(continuation.q) ? continuation.q : []).map(x=>String(x||'').trim()).filter(Boolean).slice(0,6);
  const deep = await findAIScanDeepOfferSearch(queryCandidates, identity, evidence, barcode, country, env);
  let primaryQuery = String(deep.primaryQuery || queryCandidates[0] || identity.canonicalQuery || barcode || '').trim();
  const candidatePool = Array.isArray(deep.candidatePool) ? deep.candidatePool : [];

  // First use the exact/title and trusted-retailer gates so useful results survive even
  // when retailer thumbnails are blocked. Then add pixel verification where images load.
  const textQualified = qualifyFindAICachedListings(candidatePool, identity, queryCandidates.length ? queryCandidates : [primaryQuery], evidence, country);
  let visualQualified = await promiseWithin(
    qualifyAndVerifyFindAIListings(candidatePool, identity, queryCandidates.length ? queryCandidates : [primaryQuery], evidence, env, bytes, country),
    12500,
    []
  );
  let listings = findAIScanDiversifyListings(mergeFindAIScanPools(textQualified, visualQualified), 12, primaryQuery, country);
  const market = findAIMarketData(listings);
  const productName = findAIIdentityDisplayName(identity, primaryQuery);
  const web = deep.webDiscovery || {};
  const sourceCount = new Set(listings.map(findAIScanSourceKey)).size;
  const scanKnowledge = await promiseWithin(findAIScanPersistKnowledge({
    identity, evidence, barcode, imageHash, country, query:primaryQuery, queryVariants:queryCandidates, listings, env,
    preferredProductKey:String(deep.knownScan&&deep.knownScan.productKey||deep.directIndex&&deep.directIndex.productKey||web.webIndexProductKey||'')
  }), 3200, {stored:false,retailerOffersStored:0});
  return {
    reply:listings.length?`FindAI found ${sourceCount} live source${sourceCount===1?'':'s'} for ${productName}.`:`FindAI identified ${productName}, but no verified live offer was returned by the store search.`,
    query:primaryQuery, exactQuery:primaryQuery, product:productName, productName, title:productName, brand:identity.brand||'', productLine:identity.productLine||'', model:identity.model||'', variant:identity.variant||'', category:identity.category||'', size:identity.size||'', barcode,
    visibleText:identity.visibleText||[], requiredTerms:identity.requiredTerms||[], confidence:identity.confidence, identity, market:{...market,totalAvailable:candidatePool.length}, listings, items:listings, country, kind:'product',
    meta:{ scanner:FINDAI_SCAN_VERSION,phase:'expand',deepSearchPending:false,independentRecognition:true,listingVerificationPass:true,directMultiImageVerification:true,sourceCount,rawListingCandidates:candidatePool.length,qualifiedListings:listings.length,textQualifiedCount:textQualified.length,visualVerifiedCount:listings.filter(x=>x&&x._findaiMatchMethod==='visual').length,webDiscoveryCount:Number(web&&web.items&&web.items.length||0),webDiscoveryBraveCalls:0,webIndexCount:Number(web&&web.webIndexCount||0),scanKnowledgeHit:!!(deep.knownScan&&deep.knownScan.hit),scanKnowledgeStored:!!(scanKnowledge&&scanKnowledge.stored),scanRetailerOffersStored:Number(scanKnowledge&&scanKnowledge.retailerOffersStored||0),searchQueries:deep.searchQueries||queryCandidates.slice(0,2),laneCounts:deep.laneCounts||{},marketplaceImageSearchUsed:false,independentOfMarketplaceImageRecognition:true,elapsedMs:Date.now()-startedAt }
  };
}

async function runHybridVisionSearch({ imageBase64, bytes, country, userMsg, barcodeHint, env }) {
  // FindAI Universal Visual Scan:
  // 1) independently identify the photographed product from the pixels,
  // 2) search FindAI's whole shopping engine (marketplaces + retailers + D1 + live web),
  // 3) compare candidate listing images back against the original photo,
  // 4) reuse FindAI's persistent scan/product index and verified retailer offers on later scans.
  // eBay remains only a normal listing source; it is never used to recognise the image.
  const barcode = findAIValidBarcodeHint(barcodeHint);
  const imageHash = await findAIImageHash(bytes);
  const cacheKey = imageHash ? `findai-scan:${FINDAI_SCAN_VERSION}:${country}:${barcode || 'none'}:${imageHash}` : '';
  if (cacheKey && env && env.CACHE) {
    try {
      const cached = await env.CACHE.get(cacheKey, 'json');
      if (cached && cached.meta && cached.meta.scanner === FINDAI_SCAN_VERSION) return { ...cached, meta: { ...cached.meta, cached: true } };
    } catch (_) {}
  }

  const startedAt = Date.now();
  let analysis = await promiseWithin(
    identifyFindAIProduct(bytes, env),
    12000,
    { identity: null, evidence: null, quality: null, errors: ['Full FindAI identity analysis timed out'] }
  );
  if (!analysis || !analysis.identity) {
    analysis = await promiseWithin(
      identifyFindAIProductFast(bytes, env),
      3800,
      { identity: null, evidence: null, quality: null, errors: ['Fast FindAI identity analysis timed out'] }
    );
  }

  let identity = analysis && analysis.identity || {
    kind: 'product', brand: '', productLine: '', model: '', variant: '', category: '', size: '',
    visibleText: [], canonicalQuery: '', queryVariants: [], requiredTerms: [], negativeTerms: [],
    confidence: null, needsAnotherAngle: false, angleRequest: ''
  };
  const evidence = analysis && analysis.evidence || {};
  const userHint = String(userMsg || '').replace(/\s+/g, ' ').trim().slice(0, 120);
  if (barcode) identity = { ...identity, barcode };

  if (identity.kind === 'not_product' && !barcode) {
    return {
      reply: 'I could not identify a sellable product in that photo. Try filling the frame with one item.',
      query: '', exactQuery: '', product: '', productName: '', title: '', brand: '', productLine: '', model: '', variant: '', category: '', size: '',
      visibleText: identity.visibleText || [], requiredTerms: identity.requiredTerms || [], confidence: identity.confidence,
      needsAnotherAngle: true, angleRequest: identity.angleRequest || 'Photograph one product clearly, with the front label or model details visible.',
      identity, market: { lowest: null, average: null, median: null, listingCount: 0, currency: currencyFor(country) },
      items: [], listings: [], country, kind: 'not_product',
      meta: { scanner: FINDAI_SCAN_VERSION, independentRecognition: true, identityQuality: 1, listingSource: 'FindAI universal shopping search', cached: false, elapsedMs: Date.now() - startedAt }
    };
  }

  // Do not confuse "the model returned JSON" with "the product was identified".
  // v44 could accept an object with empty fields and later display "Product matches".
  // v45 requires a real searchable identity, or it uses OCR evidence to retrieve likely
  // products from FindAI's shopping engine and asks the resolver to reconcile them.
  let identityQuality = findAIIdentityQuality(identity, evidence, barcode);
  const evidenceSeedQueries = findAIEvidenceSeedQueries(evidence, userHint);
  let recoverySearch = null;
  let recoveryQuery = '';
  if (!identityQuality.valid && !barcode && evidenceSeedQueries.length) {
    recoveryQuery = evidenceSeedQueries[0];
    recoverySearch = await promiseWithin(
      findAIUniversalScanSearch(recoveryQuery, country, env),
      12000,
      { items: [], meta: {}, correctedQuery: recoveryQuery, error: 'Retrieval-assisted identity search timed out' }
    );
    if (recoverySearch && Array.isArray(recoverySearch.items) && recoverySearch.items.length) {
      identity = await promiseWithin(
        refineFindAIIdentityFromCandidates(identity, evidence, recoverySearch.items, env),
        5200,
        identity
      );
      if (barcode) identity = { ...identity, barcode };
      identityQuality = findAIIdentityQuality(identity, evidence, barcode);
    }
  }

  if (!identityQuality.valid && !barcode) {
    return {
      reply: 'I can see a product, but I could not identify it confidently enough to price the correct item. Try the front label, model number or another angle.',
      query: recoveryQuery || '', exactQuery: '', product: '', productName: '', title: '',
      brand: identity.brand || '', productLine: identity.productLine || '', model: identity.model || '', variant: identity.variant || '', category: identity.category || '', size: identity.size || '',
      visibleText: identity.visibleText || [], requiredTerms: identity.requiredTerms || [], confidence: identity.confidence,
      needsAnotherAngle: true,
      angleRequest: identity.angleRequest || 'Photograph the product so its brand, front label, set name or model number is clearly visible.',
      identity,
      market: { lowest: null, average: null, median: null, listingCount: 0, currency: currencyFor(country) },
      items: [], listings: [], country, kind: 'unresolved_product',
      meta: {
        scanner: FINDAI_SCAN_VERSION,
        independentRecognition: true,
        identityQuality: identityQuality.score,
        identityQualityReasons: identityQuality.reasons || [],
        retrievalAssistedIdentity: !!recoverySearch,
        recoveryQuery,
        marketplaceImageSearchUsed: false,
        independentOfMarketplaceImageRecognition: true,
        visionErrors: analysis && analysis.errors || [],
        cached: false,
        elapsedMs: Date.now() - startedAt
      }
    };
  }

  const identityQueries = findAIQueryVariants(identity, evidence);
  const canonical = String(identity.canonicalQuery || identityQueries[0] || '').replace(/\s+/g, ' ').trim();
  const queryCandidates = [canonical, ...identityQueries, ...evidenceSeedQueries, userHint]
    .filter(Boolean)
    .filter((v, i, a) => a.findIndex(x => hybridNormalise(x) === hybridNormalise(v)) === i)
    .slice(0, 6);
  let primaryQuery = queryCandidates[0] || (barcode ? barcode : '');

  // A valid UPC/EAN/GTIN is an excellent deterministic clue, but we use it as an
  // additional marketplace lookup rather than replacing the visual identity.
  const barcodePromise = barcode
    ? promiseWithin(searchListings(barcode, '', country, env), 5200, { items: [], meta: {}, error: 'Barcode lookup timed out' })
    : Promise.resolve({ items: [], meta: {} });
  const knownScanPromise = promiseWithin(
    findAIScanReadKnownOffers(identity, barcode, country, env),
    5200,
    { items: [], productKey: '', scanProductKey: '', hit: false }
  );
  const primaryPromise = primaryQuery
    ? promiseWithin(findAIUniversalScanSearch(primaryQuery, country, env), 15000, { items: [], meta: {}, correctedQuery: primaryQuery, error: 'Universal shopping search timed out' })
    : Promise.resolve({ items: [], meta: {}, correctedQuery: '' });

  const [primarySearch, barcodeSearch, knownScan] = await Promise.all([primaryPromise, barcodePromise, knownScanPromise]);
  if (primarySearch && primarySearch.correctedQuery) primaryQuery = String(primarySearch.correctedQuery || primaryQuery).trim();
  let candidatePool = mergeFindAIScanPools(knownScan && knownScan.items, recoverySearch && recoverySearch.items, primarySearch && primarySearch.items, barcodeSearch && barcodeSearch.items);
  let usedQueries = [primaryQuery, recoveryQuery, barcode].filter(Boolean);
  let secondaryMeta = recoverySearch && recoverySearch.meta || {};

  // If the first universal pass is thin, try one alternate precise identity. This
  // keeps normal scans fast while giving unusual editions/colourways another route
  // into retailer and marketplace inventories.
  let semanticPreview = prepareFindAIListingCandidates(candidatePool, identity, queryCandidates);
  const alternate = queryCandidates.find(q => hybridNormalise(q) !== hybridNormalise(primaryQuery));
  if (semanticPreview.length < 8 && alternate) {
    const secondary = await promiseWithin(
      findAIUniversalScanSearch(alternate, country, env),
      10500,
      { items: [], meta: {}, correctedQuery: alternate, error: 'Alternate shopping search timed out' }
    );
    candidatePool = mergeFindAIScanPools(candidatePool, secondary && secondary.items);
    secondaryMeta = { ...(secondaryMeta || {}), ...(secondary && secondary.meta || {}) };
    usedQueries.push(alternate);
    semanticPreview = prepareFindAIListingCandidates(candidatePool, identity, queryCandidates);
  }

  // Verify the actual listing photos against the user's scan. Retailer titles can
  // be wrong/ambiguous; pixels are the final check wherever candidate images load.
  let listings = await promiseWithin(
    qualifyAndVerifyFindAIListings(candidatePool, identity, queryCandidates, evidence, env, bytes, country),
    14500,
    []
  );

  // FindAI-owned recognition only. eBay can contribute ordinary text/API listings to
  // candidatePool, but its image-search endpoint is deliberately never called here.
  listings = findAIScanDiversifyListings(listings, 12, primaryQuery, country);
  const market = findAIMarketData(listings);
  const structuredName = [identity.brand, identity.productLine, identity.variant, identity.model, identity.size].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim();
  const productName = structuredName || primaryQuery || (barcode ? `Product ${barcode}` : '');
  const metaParts = [primarySearch && primarySearch.meta || {}, secondaryMeta];
  const webBraveCalls = 0;
  const webIndexCount = Math.max(...metaParts.map(m => Number(m && m.webIndexCount || 0)), 0);
  const webDiscoveryCount = metaParts.reduce((n, m) => n + Number(m && m.webDiscoveryCount || 0), 0);
  const sourceCount = new Set(listings.map(findAIScanSourceKey)).size;
  const visualVerifiedCount = listings.filter(item => item && item._findaiMatchMethod === 'visual').length;
  const scanKnowledge = await promiseWithin(
    findAIScanPersistKnowledge({
      identity, evidence, barcode, imageHash, country, query: primaryQuery || canonical, queryVariants: queryCandidates,
      listings, env, preferredProductKey: String(knownScan && knownScan.productKey || primarySearch && primarySearch.meta && primarySearch.meta.webIndexProductKey || '')
    }),
    4200,
    { stored: false, retailerOffersStored: 0, productKey: '' }
  );

  const payload = {
    reply: listings.length
      ? `FindAI identified ${productName} and matched it across the shopping web.`
      : (identity.angleRequest || `FindAI identified ${productName}, but no close live listing passed verification.`),
    query: primaryQuery,
    exactQuery: primaryQuery,
    product: productName,
    productName,
    title: productName,
    brand: identity.brand || '',
    productLine: identity.productLine || '',
    exactProductName: productName,
    model: identity.model || '',
    variant: identity.variant || '',
    category: identity.category || '',
    size: identity.size || '',
    barcode: barcode || '',
    visibleText: identity.visibleText || [],
    requiredTerms: identity.requiredTerms || [],
    confidence: identity.confidence,
    needsAnotherAngle: !!identity.needsAnotherAngle && !listings.length,
    angleRequest: identity.angleRequest || '',
    identity,
    market: { ...market, totalAvailable: candidatePool.length },
    items: listings,
    listings,
    country,
    kind: 'product',
    meta: {
      scanner: FINDAI_SCAN_VERSION,
      independentRecognition: true,
      recognitionPasses: analysis && analysis.identity ? (recoverySearch ? 4 : 3) : 0,
      recognitionModels: [FINDAI_PRIMARY_VISION_MODEL, FINDAI_OCR_VISION_MODEL, FINDAI_IDENTITY_RESOLVER_MODEL],
      identityQuality: identityQuality.score,
      retrievalAssistedIdentity: !!recoverySearch,
      recoveryQuery,
      listingVerificationPass: true,
      directMultiImageVerification: true,
      visualVerifiedCount,
      candidateVisualCalls: Math.ceil(Math.min(FINDAI_VISUAL_CANDIDATE_LIMIT, semanticPreview.length || candidatePool.length) / FINDAI_VISUAL_BATCH_SIZE),
      marketplaceImageSearchUsed: false,
      independentOfMarketplaceImageRecognition: true,
      listingSource: 'FindAI universal shopping search: marketplaces + retailers + D1 web index + live web discovery, followed by direct image verification',
      searchQueries: [...new Set(usedQueries.filter(Boolean))].slice(0, 4),
      barcodeUsed: !!barcode,
      rawListingCandidates: candidatePool.length,
      qualifiedListings: listings.length,
      sourceCount,
      webDiscoveryCount,
      webDiscoveryBraveCalls: webBraveCalls,
      webIndexCount,
      scanKnowledgeHit: !!(knownScan && knownScan.hit),
      scanKnowledgeStored: !!(scanKnowledge && scanKnowledge.stored),
      scanRetailerOffersStored: Number(scanKnowledge && scanKnowledge.retailerOffersStored || 0),
      scanProductKey: String(scanKnowledge && scanKnowledge.scanProductKey || knownScan && knownScan.scanProductKey || ''),
      visionErrors: analysis && analysis.errors || [],
      elapsedMs: Date.now() - startedAt,
      userHint,
      cached: false
    }
  };
  if (cacheKey && env && env.CACHE && listings.length) {
    try { await env.CACHE.put(cacheKey, JSON.stringify(payload), { expirationTtl: 900 }); } catch (_) {}
  }
  return payload;
}

// ── AliExpress signing (HMAC-SHA256, sign_method=sha256) ────────────────────
// crypto.subtle in Workers does NOT support MD5, so we use the sha256 method:
//   1. add system params (app_key, method, sign_method, timestamp(ms), v)
//   2. sort ALL params by ASCII key
//   3. build string = key1value1key2value2...  (no separators)
//   4. sign = HMAC-SHA256(string, APP_SECRET) as UPPERCASE hex
async function hmacSha256Hex(message, secret) {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    'raw', enc.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false, ['sign']
  );
  const sigBuf = await crypto.subtle.sign('HMAC', key, enc.encode(message));
  return [...new Uint8Array(sigBuf)].map(b => b.toString(16).padStart(2, '0')).join('').toUpperCase();
}

async function aliSignedCall(method, businessParams, env) {
  const params = {
    app_key: env.ALI_APP_KEY,
    method,
    sign_method: 'sha256',
    timestamp: String(Date.now()), // milliseconds
    v: '2.0',
    ...businessParams,
  };

  const sortedKeys = Object.keys(params).sort();
  const baseString = sortedKeys.map(k => `${k}${params[k]}`).join('');
  params.sign = await hmacSha256Hex(baseString, env.ALI_APP_SECRET);

  const body = new URLSearchParams(params).toString();
  const res = await fetch(ALI_GATEWAY, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded;charset=utf-8' },
    body,
  });
  return res.json();
}

// Dig the product array out of AliExpress's nested response (shape varies)
function extractAliProducts(data) {
  if (!data || typeof data !== 'object') return { products: [], error: 'empty response' };

  if (data.error_response) {
    const e = data.error_response;
    return { products: [], error: `Ali error ${e.code || ''} ${e.sub_msg || e.msg || JSON.stringify(e)}` };
  }

  const respKey = Object.keys(data).find(k => k.endsWith('_response'));
  const root   = respKey ? data[respKey] : data;
  const rr     = root?.resp_result || root;
  const result = rr?.result || rr;

  let products = result?.products?.product ?? result?.products ?? [];
  if (!Array.isArray(products)) products = products ? [products] : [];

  const respCode = rr?.resp_code;
  if (respCode && respCode !== 200 && products.length === 0) {
    return { products: [], error: `Ali resp_code ${respCode}: ${rr?.resp_msg || ''}` };
  }
  return { products, error: null };
}

function mapAliProduct(p, country) {
  const price = parseFloat(
    p.target_sale_price ?? p.sale_price ?? p.target_original_price ?? 0
  ) || 0;
  return {
    source: 'AliExpress',
    itemId: String(p.product_id || p.product_id_str || ''),
    title:  (p.product_title || '').replace(/[\u2014\u2013]/g, '-'),
    price,
    currency: p.target_sale_price_currency || currencyFor(country),
    url:    p.promotion_link || p.product_detail_url || '',
    image:  p.product_main_image_url || null,
    location: 'CN',
    condition: 'New',
    listingType: 'FIXED_PRICE',
  };
}

async function searchAliExpress(keywords, country, env, limit = 12) {
  try {
    const business = {
      keywords,
      page_no: '1',
      page_size: String(Math.min(limit, 50)),
      target_currency: currencyFor(country),
      target_language: 'EN',
      tracking_id: ALI_TRACKING_ID,
      ship_to_country: shipCountry(country),
      sort: 'LAST_VOLUME_DESC', // most-ordered first ≈ most popular
    };
    const data = await aliSignedCall('aliexpress.affiliate.product.query', business, env);
    const { products, error } = extractAliProducts(data);
    if (error) return { items: [], error, raw: data };
    const items = products.map(p => mapAliProduct(p, country)).filter(i => i.url && i.title);
    return { items, total: items.length, error: null };
  } catch (e) {
    return { items: [], error: String(e.message || e) };
  }
}

// Fisher–Yates shuffle (non-mutating)
function shuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// Build a deduped pool (image + tracked link only) from an array of search results
function poolFrom(results) {
  const pool = [], seen = new Set();
  for (const r of results) {
    for (const it of (r.items || [])) {
      if (it.image && it.url && !seen.has(it.itemId)) { seen.add(it.itemId); pool.push(it); }
    }
  }
  return pool;
}

// Homepage featured pools: a pool of Pop Mart / Labubu items + a pool from a
// second category. The front-end caches these and rotates through them so the
// two featured cards refresh independently and move around.
//   ↓↓↓ To change the second category, edit OTHER_TERMS below ↓↓↓
async function aliHomepagePools(env, country = 'AU') {
  const POPMART_TERMS = ['labubu doll', 'labubu the monsters figure']; // the actual Labubu figure, not keychains/accessories
  const OTHER_TERMS   = ['sneakers', 'running shoes']; // ← slot 2: very popular shoes (Ali sorts by most-ordered)

  const [popRes, otherRes] = await Promise.all([
    Promise.all(POPMART_TERMS.map(t => searchAliExpress(t, country, env, 20).catch(() => ({ items: [] })))),
    Promise.all(OTHER_TERMS.map(t   => searchAliExpress(t, country, env, 20).catch(() => ({ items: [] })))),
  ]);

  return {
    popmart: shuffle(poolFrom(popRes)).slice(0, 10),
    other:   shuffle(poolFrom(otherRes)).slice(0, 10),
  };
}

// Homepage preview searches. These run server-side and the combined pool is
// cached at the edge (see the ?previews=1 route) so the homepage loads from ONE
// fast call instead of 9–16 live searches per visit. The front-end shuffles the
// returned pool client-side, so each visitor still sees a fresh-looking grid.
//   ↓↓↓ Edit this list to change what the homepage features ↓↓↓
const PREVIEW_QUERIES = [
  // Sneakers — Yeezy 350 only, Dunks, Jordan 1 only
  'yeezy 350 v2', 'nike dunk low',
  'air jordan 1 high og', 'travis scott jordan 1', 'off white jordan 1',
  // Streetwear
  'supreme box logo hoodie', 'bape shark hoodie',
  // Bags
  'louis vuitton bag',
  // Watches (MoonSwatch = the Omega x Swatch; Royal Oak = "normal" AP)
  'rolex daytona', 'rolex submariner', 'omega swatch moonswatch', 'audemars piguet royal oak',
  // Tech
  'ps5 console', 'airpods max',
  // Jewellery + collectibles
  'cartier love bracelet', 'pokemon charizard psa 10',
];

// ── Query understanding (colour / price ceiling / core product words) ───────
const COLOR_WORDS = ['red','orange','yellow','green','blue','navy','teal','turquoise','cyan',
  'purple','violet','magenta','pink','rose','black','white','cream','beige','tan','khaki',
  'brown','grey','gray','gold','silver','bronze','maroon'];

// Some product nouns show up under different words in messy AliExpress titles.
const TOKEN_SYNONYMS = {
  shirt: ['shirt','tee','tshirt','t-shirt'],
  tee: ['tee','tshirt','t-shirt','shirt'],
  tshirt: ['tshirt','t-shirt','tee','shirt'],
  't-shirt': ['t-shirt','tshirt','tee','shirt'],
  shoe: ['shoe','sneaker','trainer','footwear'],
  shoes: ['shoe','sneaker','trainer','footwear'],
  sneaker: ['sneaker','shoe','trainer'],
  sneakers: ['sneaker','shoe','trainer'],
  phone: ['phone','smartphone','mobile'],
  ps5: ['ps5','playstation 5','playstation5'],
  ps4: ['ps4','playstation 4','playstation4'],
  bo3: ['bo3','black ops 3','blackops3','call of duty black ops 3'],
  airpods: ['airpods','air pods'],
  iphone: ['iphone','apple iphone'],
  hoodie: ['hoodie','sweatshirt','pullover'],
  sweater: ['sweater','jumper','pullover','knit'],
  jumper: ['jumper','sweater','pullover','knit'],
  jacket: ['jacket','coat'],
  bag: ['bag','handbag','backpack','tote','purse'],
  pants: ['pant','trouser'],
  trousers: ['trouser','pant'],
  dress: ['dress','gown'],
};

// Words that carry no product meaning, so they aren't required to appear in titles.
const FILLER_WORDS = new Set(['find','me','a','an','the','some','please','show','get','got',
  'want','wanted','looking','look','for','i','im',"i'm",'need','needed','any','of','with',
  'that','this','is','are','to','my','can','you','search','searching','list','listing',
  'listings','item','items','product','products','buy','cheap','cheapest','best','top','good',
  'great','nice','new','latest','cool','around','about','something','stuff','things','thing',
  'under','below','than','less','max','maximum','dollars','dollar','aud','usd','price','priced',
  'costing','cost','only','just']);

function parseQuery(q) {
  const lower = ' ' + q.toLowerCase().replace(/[^a-z0-9$.\s-]/g, ' ') + ' ';
  let parsedMax = 0;
  const m = lower.match(/(?:under|below|less\s+than|cheaper\s+than|max|maximum|up\s+to|<)\s*\$?\s*([\d,]+(?:\.\d+)?)/);
  if (m) parsedMax = parseFloat(m[1].replace(/,/g, '')) || 0;

  const colors = COLOR_WORDS.filter(c => new RegExp(`\\b${c}\\b`).test(lower));

  const coreTokens = lower.split(/\s+/)
    .map(w => w.trim())
    .filter(w => w.length >= 3 && !FILLER_WORDS.has(w) && !colors.includes(w) && !/^\$?[\d,.]+$/.test(w));

  return { colors, coreTokens, parsedMax };
}

// "labubu under 500" → "labubu" : strip price phrases so the marketplace query stays clean.
function stripPricePhrases(q) {
  return q
    .replace(/(?:under|below|less\s+than|cheaper\s+than|max|maximum|up\s+to|<)\s*\$?\s*[\d,]+(?:\.\d+)?(?:\s*(?:dollars?|aud|usd))?/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Map colloquial sneaker/product slang to the explicit product name a marketplace expects,
// so the search doesn't misfire. e.g. "air forces" colloquially means the Nike Air Force 1
// SNEAKER — without this it matches Royal Air Force militaria on eBay. Only rewrites when the
// shopper clearly isn't asking for the military item (no "royal"/"raf"/"rank"/"badge").
function normalizeKeywords(kw) {
  let s = ' ' + String(kw || '') + ' ';
  const meansMilitary = /\b(royal|raf|rank|rank\s*slide|slides?|badge|insignia|patch|crest|regiment|squadron|uniform)\b/i.test(s);
  if (!meansMilitary) {
    // "air force ones / air force 1s / af1 / air forces / air force" → Nike Air Force 1
    s = s.replace(/\bair\s?force\s?(ones|one|1s|1)\b/gi, ' nike air force 1 ')
         .replace(/\baf\s?1s?\b/gi, ' nike air force 1 ')
         .replace(/\bair\s?forces\b/gi, ' nike air force 1 ');
    if (/\bair\s?force\b/i.test(s) && !/nike air force 1/i.test(s)) {
      s = s.replace(/\bair\s?force\b/gi, ' nike air force 1 ');
    }
    s = s.replace(/\bnike\s+nike\b/gi, 'nike'); // collapse if the user already said "nike"
  }
  // A couple of other common shorthands that help eBay land the right item.
  s = s.replace(/\bjordan\s?(ones|one|1s|1)\b/gi, ' air jordan 1 ')
       .replace(/\bnike\s+air jordan\b/gi, 'air jordan');
  return s.replace(/\s+/g, ' ').trim();
}

// Popular brands/products people actually search — used to gently fix typos so a
// misspelling like "dior suavage" still finds the 900+ "sauvage" listings instead of 2.
const KNOWN_TERMS = ['sauvage','aventus','creed','dior','gucci','prada','versace','balenciaga',
  'givenchy','chanel','louis','vuitton','hermes','burberry','fendi','valentino','moncler',
  'nike','adidas','yeezy','jordan','puma','reebok','converse','asics','samba','gazelle',
  'babolat','aero','pure','strike','wilson','head','yonex','tecnifibre','dunlop',
  'rolex','omega','cartier','patek','audemars','breitling','tudor','seiko','tissot','hublot',
  'labubu','popmart','smiski','pokemon','charizard','funko','juggernog','spongebob',
  'lego','star','wars','vampire','harry','potter','monster','fighters','motorcycle',
  'fridge','refrigerator','controller','console','headphones','earbuds',
  'apple','iphone','ipad','macbook','airpods','samsung','galaxy','playstation','nintendo','xbox',
  'supreme','bape','stussy','carhartt','patagonia','pandora','swarovski','tiffany'];

// Levenshtein edit distance (bails early when the words are clearly far apart).
function editDistance(a, b) {
  const m = a.length, n = b.length;
  if (Math.abs(m - n) > 2) return 99;
  const dp = Array.from({ length: m + 1 }, (_, i) => { const row = new Array(n + 1).fill(0); row[0] = i; return row; });
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      dp[i][j] = Math.min(dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + cost);
    }
  }
  return dp[m][n];
}

// Damerau-Levenshtein distance also treats adjacent transpositions as one edit, which
// matters for product/model typos such as "aeor" -> "aero" and "savauge" -> "sauvage".
function damerauEditDistance(a, b) {
  a = String(a || ''); b = String(b || '');
  if (a === b) return 0;
  const m = a.length, n = b.length;
  if (!m) return n; if (!n) return m;
  if (Math.abs(m - n) > 2) return 99;
  const d = Array.from({ length: m + 1 }, (_, i) => {
    const row = new Array(n + 1).fill(0); row[0] = i; return row;
  });
  for (let j = 0; j <= n; j++) d[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + cost);
      if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) {
        d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1);
      }
    }
  }
  return d[m][n];
}

// Product spelling correction is intentionally conservative. Long words can move by
// two edits; short 4-letter model names only move when the match is unique and the
// typo is a transposition/one-edit near miss. This catches searches such as
// "dior savauge" -> "dior sauvage" and "babolat aeor" -> "babolat aero"
// without turning ordinary short English words into brands.
function correctSpelling(kw) {
  const knownSet = new Set(KNOWN_TERMS);
  const words = String(kw || '').split(/\s+/);
  const context = new Set(words.map(w => w.toLowerCase().replace(/[^a-z0-9]/g, '')).filter(Boolean));
  return words.map(w => {
    const lw = w.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (lw.length < 3 || knownSet.has(lw) || /^\d+$/.test(lw)) return w;
    let best = null, bestD = 99, ties = 0;
    for (const term of KNOWN_TERMS) {
      if (!term || term[0] !== lw[0] || Math.abs(term.length - lw.length) > 2) continue;
      const d = damerauEditDistance(lw, term);
      if (d < bestD) { bestD = d; best = term; ties = 1; }
      else if (d === bestD) ties++;
    }
    if (!best || bestD <= 0 || ties !== 1) return w;
    if (lw.length >= 5 && bestD <= 2) return best;
    // Four-letter product/model words get the tighter treatment. "aeor" is a
    // transposition away from "aero"; requiring nearby product context avoids
    // aggressive corrections of normal prose.
    const productContext = [...context].some(t => ['babolat','wilson','head','yonex','tecnifibre','dunlop','nike','adidas','sony','apple','dior','lego','pokemon','playstation','xbox','nintendo'].includes(t));
    if (lw.length === 3 && bestD <= 1 && productContext) return best;
    return (lw.length === 4 && bestD <= 1 && productContext) ? best : w;
  }).join(' ');
}


// v60: learn typo corrections from product families that already have verified offers.
function findAIWholeEditDistance(a,b){
  a=String(a||'');b=String(b||'');
  if(a===b)return 0;if(!a.length)return b.length;if(!b.length)return a.length;
  let prev=Array.from({length:b.length+1},(_,i)=>i),cur=new Array(b.length+1);
  for(let i=1;i<=a.length;i++){
    cur[0]=i;
    for(let j=1;j<=b.length;j++){
      const cost=a[i-1]===b[j-1]?0:1;
      cur[j]=Math.min(cur[j-1]+1,prev[j]+1,prev[j-1]+cost);
    }
    const swap=prev;prev=cur;cur=swap;
  }
  return prev[b.length];
}
function findAITypoNorm(value){return String(value||'').toLowerCase().replace(/[’']/g,'').replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();}
function findAITypoCompact(value){return findAITypoNorm(value).replace(/\s+/g,'');}
function findAITypoCodes(value){
  let n=findAITypoNorm(value)
    .replace(/\bones?\b/g,' 1 ').replace(/\btwos?\b/g,' 2 ').replace(/\bthrees?\b/g,' 3 ')
    .replace(/\bfours?\b/g,' 4 ').replace(/\bfives?\b/g,' 5 ').replace(/\bsixes?\b/g,' 6 ')
    .replace(/\bsevens?\b/g,' 7 ').replace(/\beights?\b/g,' 8 ').replace(/\bnines?\b/g,' 9 ').replace(/\btens?\b/g,' 10 ');
  return [...new Set((n.match(/\b(?:[a-z]+\d+[a-z0-9]*|\d+[a-z]+|\d+)\b/g)||[]))].sort();
}
function findAITypoExactTokens(value){
  const stop=new Set(['the','and','for','with','from','new','used','buy','find','show','best','cheap','price','item','product']);
  return new Set(findAITypoNorm(value).split(/\s+/).filter(x=>x.length>=3&&!stop.has(x)));
}
function findAITypoSimilarity(a,b){
  const aa=findAITypoCompact(a),bb=findAITypoCompact(b);if(!aa||!bb)return 0;
  const max=Math.max(aa.length,bb.length);if(Math.abs(aa.length-bb.length)>Math.max(5,Math.floor(max*.38)))return 0;
  return Math.max(0,1-findAIWholeEditDistance(aa,bb)/max);
}
async function findAILearnedQueryCorrection(query,country,env){
  let base=findAINormaliseProductAliases(correctSpelling(normalizeKeywords(String(query||''))));
  base=String(base||'').replace(/\s+/g,' ').trim().slice(0,180);
  if(!base||base.length<6||!env||!env.DB||!webIndexEnabled(env))return base;
  try{
    await ensureWebDiscoverySchema(env);
    const c=webDiscoveryCountry(country);
    // Exact aliases are the overwhelmingly common case. Resolve them with the primary key
    // first so normal searches do not pay for a fuzzy candidate scan.
    const exactAliasKey=webIndexAliasKey(base);
    if(exactAliasKey){
      const exact=await env.DB.prepare(`SELECT a.product_key FROM web_index_aliases a
        JOIN web_index_markets m ON m.product_key=a.product_key AND m.market_country=a.market_country
        WHERE a.alias_key=? AND a.market_country=? AND m.known_offer_count>0 LIMIT 1`).bind(exactAliasKey,c).first();
      if(exact&&exact.product_key)return base;
    }
    // For an unseen/misspelled phrase, recent successful aliases are more useful than an old
    // globally-popular product. The scan stays tightly bounded and only considers families
    // that already have verified offers in this shopper's market.
    const rows=await env.DB.prepare(`SELECT a.alias_query,p.canonical_query,m.search_count,a.last_seen_at
      FROM web_index_aliases a
      JOIN web_index_products p ON p.product_key=a.product_key
      JOIN web_index_markets m ON m.product_key=a.product_key AND m.market_country=a.market_country
      WHERE a.market_country=? AND m.known_offer_count>0
      ORDER BY a.last_seen_at DESC,m.search_count DESC LIMIT 140`).bind(c).all();
    const baseCodes=findAITypoCodes(base),baseTokens=findAITypoExactTokens(base),baseWords=findAITypoNorm(base).split(/\s+/).filter(Boolean),scored=[];
    for(const row of (rows.results||[])){
      for(const candidateRaw of [row.alias_query,row.canonical_query]){
        const candidate=String(candidateRaw||'').replace(/\s+/g,' ').trim();if(!candidate)continue;
        if(findAITypoNorm(candidate)===findAITypoNorm(base))return base;
        if(baseCodes.join('|')!==findAITypoCodes(candidate).join('|'))continue;
        const words=findAITypoNorm(candidate).split(/\s+/).filter(Boolean);if(Math.abs(words.length-baseWords.length)>2)continue;
        const sim=findAITypoSimilarity(base,candidate),threshold=base.length>=18?.80:(base.length>=12?.84:.90);if(sim<threshold)continue;
        const ct=findAITypoExactTokens(candidate);let overlap=0;for(const t of baseTokens)if(ct.has(t))overlap++;
        if(overlap===0&&sim<.91)continue;
        const popularity=Math.min(.025,Math.log10(1+Number(row.search_count||0))*.006);
        scored.push({candidate,score:sim+Math.min(2,overlap)*.018+popularity,sim});
      }
    }
    scored.sort((a,b)=>b.score-a.score);if(!scored.length)return base;
    const best=scored[0],second=scored[1];if(second&&best.score-second.score<.018&&best.sim<.94)return base;
    return findAINormaliseProductAliases(correctSpelling(normalizeKeywords(best.candidate)))||base;
  }catch(_){return base;}
}


// ── Conservative live-web product discovery ───────────────────────────────
// This complements official marketplace APIs / product feeds; it never replaces them.
// Cost guardrails are fail-closed: without D1, FindAI simply falls back to its normal
// API results; it serves its persistent retailer index without an external general-search provider.
// External general-search calls were retired in v109; product-page refreshes are direct.
// Known retailer URLs are refreshed directly; product-page refreshes
// are direct HTTP fetches controlled by FindAI.
const WEB_DISCOVERY_VERSION = 'v20-availability-safe';
const AUTHORITY_RESOLVER_VERSION = 'v67-adaptive-global-resolver';
const HOME_PREVIEW_VERSION = 'v54-availability-safe';
// Retailer prices move, so successful web offers refresh several times a day.
// Failed discovery is retried much sooner than v1 so one blocked/weak search does not
// hide the wider web for hours.
const WEB_DISCOVERY_CACHE_TTL_MS = 6 * 60 * 60 * 1000;
const WEB_DISCOVERY_NEGATIVE_TTL_MS = 45 * 60 * 1000;
// Persistent FindAI shopping-index controls. These are deliberately conservative:
// FindAI remembers retailer URLs in D1; subsequent searches refresh known
// retailer pages directly instead of rediscovering the same product.
let WEB_DISCOVERY_SCHEMA_READY = false;

function webDiscoveryInt(env, name, fallback, min, max) {
  const n = Number(env && env[name]);
  if (!Number.isFinite(n)) return fallback;
  return Math.max(min, Math.min(max, Math.floor(n)));
}

// v109: external general-web search providers are disabled. FindAI serves its own
// persistent retailer index and direct marketplace/merchant sources only.
function webDiscoveryEnabled(env) { return false; }
function webIndexEnabled(env) {
  const flag = String((env && env.WEB_INDEX_ENABLED) == null ? 'true' : env.WEB_INDEX_ENABLED).toLowerCase();
  return !!(env && env.DB) && !['0','false','off','no'].includes(flag);
}
function webDiscoveryCountry(code) {
  const c = String(code || 'US').toUpperCase();
  if (c === 'UK' || c === 'GB') return 'GB';
  const supported = new Set(['AR','AU','AT','BE','BR','CA','CL','DK','FI','FR','DE','HK','IN','ID','IE','IT','JP','KR','MY','MX','NL','NZ','NO','PH','PL','PT','SA','SG','ZA','ES','SE','CH','TW','TR','US']);
  return supported.has(c) ? c : 'US';
}
function webDiscoveryCurrency(country) {
  const map = {
    AR:'ARS',AU:'AUD',AT:'EUR',BE:'EUR',BR:'BRL',CA:'CAD',CL:'CLP',DK:'DKK',FI:'EUR',FR:'EUR',DE:'EUR',
    HK:'HKD',IN:'INR',ID:'IDR',IE:'EUR',IT:'EUR',JP:'JPY',KR:'KRW',MY:'MYR',MX:'MXN',NL:'EUR',NZ:'NZD',
    NO:'NOK',PH:'PHP',PL:'PLN',PT:'EUR',SA:'SAR',SG:'SGD',ZA:'ZAR',ES:'EUR',SE:'SEK',CH:'CHF',TW:'TWD',
    TR:'TRY',GB:'GBP',UK:'GBP',US:'USD'
  };
  return map[String(country || '').toUpperCase()] || 'USD';
}
function webDiscoveryCurrencyMagnitude(currency) {
  // Rough order-of-magnitude only. These are intentionally broad plausibility scalers,
  // not exchange-rate quotes. They stop a JPY/KRW/IDR price from being mistaken for a
  // 100x cents error while keeping the same product-family sanity system worldwide.
  return ({
    USD:1,AUD:1.6,GBP:0.9,EUR:1,CAD:1.5,NZD:1.8,SGD:1.5,HKD:9,CHF:1.1,
    JPY:180,KRW:1800,INR:110,IDR:22000,BRL:7,MXN:24,PLN:5,DKK:8,SEK:13,NOK:13,
    SAR:4.5,ZAR:24,MYR:6,PHP:75,TWD:42,TRY:55,ARS:1800,CLP:1300
  })[String(currency||'USD').toUpperCase()] || 1;
}
function webDiscoveryAllowsMinorUnitCorrection(currency) {
  // Avoid automatic /100 corrections in currencies commonly presented as whole-unit
  // shopping prices (JPY/KRW/IDR etc.). For normal cent-based currencies, correction is
  // still allowed only when the unscaled value is outside the family ceiling.
  return new Set(['USD','AUD','GBP','EUR','CAD','NZD','SGD','HKD','CHF','BRL','MXN','PLN','DKK','SEK','NOK','SAR','ZAR','MYR','PHP']).has(String(currency||'').toUpperCase());
}
function webDiscoveryCacheKey(query, country) {
  return `${WEB_DISCOVERY_VERSION}|${webDiscoveryCountry(country)}|${String(query || '').toLowerCase().replace(/\s+/g,' ').trim()}`;
}
const WEB_INDEX_QUALITY_MIGRATION='v51-discovery-memory-quality-1';
async function webIndexRunOfferQualityMaintenance(env) {
  if(!env||!env.DB)return;
  try{
    await env.DB.prepare(`CREATE TABLE IF NOT EXISTS web_index_maintenance (migration_key TEXT PRIMARY KEY,completed_at INTEGER NOT NULL DEFAULT 0)`).run();
    const done=await env.DB.prepare(`SELECT migration_key FROM web_index_maintenance WHERE migration_key=? LIMIT 1`).bind(WEB_INDEX_QUALITY_MIGRATION).first();
    if(done)return;
    const now=Date.now();
    // Search-engine snippets are discovery leads, not verified prices. Existing snippet-priced
    // rows are retired; authority URLs remain independently remembered by the resolver tables.
    await env.DB.prepare(`UPDATE web_index_offers SET active=0 WHERE source='web-search'`).run();
    // Collection/category pages may expose minimum/teaser prices but are not a single Buy Now
    // product. Direct product URLs nested under /collections/.../products/... are preserved.
    await env.DB.prepare(`UPDATE web_index_offers SET active=0 WHERE active=1 AND ((lower(product_url) LIKE '%/collections/%' AND lower(product_url) NOT LIKE '%/products/%') OR (((lower(product_url) LIKE '%/product-category/%') OR (lower(product_url) LIKE '%/categories/%') OR (lower(product_url) LIKE '%/category/%')) AND lower(product_url) NOT LIKE '%/product/%' AND lower(product_url) NOT LIKE '%/products/%' AND lower(product_url) NOT LIKE '%/p/%' AND lower(product_url) NOT LIKE '%/item/%') OR lower(title) LIKE '%shop all%' OR lower(title) LIKE '%trade in%' OR lower(title) LIKE '%trade-in%' OR lower(title) LIKE '%compare iphone%')`).run();

    const rows=await env.DB.prepare(`SELECT o.offer_key,o.product_key,o.variant_key,o.market_country,o.retailer_host,o.title,o.price,o.currency,o.product_url,o.source,p.canonical_query FROM web_index_offers o LEFT JOIN web_index_products p ON p.product_key=o.product_key WHERE o.active=1 ORDER BY o.last_checked_at DESC LIMIT 2500`).all();
    const statements=[]; const touched=new Set();
    for(const row of (rows.results||[])){
      const query=String(row.canonical_query||row.title||'');
      const item={title:String(row.title||''),price:Number(row.price)||0,url:String(row.product_url||''),webPriceSource:String(row.source||'')};
      if(!webDiscoveryOfferPageEligible(item,query)){
        statements.push(env.DB.prepare(`UPDATE web_index_offers SET active=0 WHERE offer_key=?`).bind(row.offer_key));
        touched.add(String(row.product_key||'')+'|'+String(row.market_country||''));
        continue;
      }
      const check=webDiscoveryBasicPriceAssessment(row.price,query,row.title,row.source,false,row.currency);
      if(!check.ok){
        statements.push(env.DB.prepare(`UPDATE web_index_offers SET active=0 WHERE offer_key=?`).bind(row.offer_key));
        touched.add(String(row.product_key||'')+'|'+String(row.market_country||''));
        continue;
      }
      if(check.scaled && Number(check.price)>0){
        const corrected=Number(check.price);
        statements.push(env.DB.prepare(`UPDATE web_index_offers SET price=?,last_price_change_at=?,last_checked_at=? WHERE offer_key=?`).bind(corrected,now,now,row.offer_key));
        statements.push(env.DB.prepare(`DELETE FROM web_index_price_history WHERE offer_key=? AND price>?`).bind(row.offer_key,corrected*20));
        statements.push(env.DB.prepare(`INSERT OR IGNORE INTO web_index_price_history(offer_key,observed_at,price,currency) VALUES(?,?,?,?)`).bind(row.offer_key,now,corrected,String(row.currency||'')));
        touched.add(String(row.product_key||'')+'|'+String(row.market_country||''));
      }
    }
    // Legacy peer-consensus cleanup. Exact-variant rows in the same market/currency should
    // never differ by an order of magnitude. With two rows, quarantine only the extreme low
    // value (the usual finance/deposit failure); with 3+ rows use the median in both directions.
    const groups=new Map();
    for(const row of (rows.results||[])){
      if(!String(row.variant_key||''))continue;
      const key=[row.product_key,row.variant_key,row.market_country,row.currency].join('|');
      if(!groups.has(key))groups.set(key,[]);
      if(Number(row.price)>0)groups.get(key).push(row);
    }
    for(const group of groups.values()){
      if(group.length<2)continue;
      const sorted=group.slice().sort((a,b)=>Number(a.price)-Number(b.price));
      if(group.length===2){
        const lo=Number(sorted[0].price),hi=Number(sorted[1].price);
        if(lo>0&&hi/lo>15){
          statements.push(env.DB.prepare(`UPDATE web_index_offers SET active=0 WHERE offer_key=?`).bind(sorted[0].offer_key));
          touched.add(String(sorted[0].product_key||'')+'|'+String(sorted[0].market_country||''));
        }
        continue;
      }
      const mid=Number(sorted[Math.floor(sorted.length/2)].price);
      if(!(mid>0))continue;
      for(const row of sorted){
        const p=Number(row.price);
        if(p>0&&(p<mid/8||p>mid*8)){
          statements.push(env.DB.prepare(`UPDATE web_index_offers SET active=0 WHERE offer_key=?`).bind(row.offer_key));
          touched.add(String(row.product_key||'')+'|'+String(row.market_country||''));
        }
      }
    }
    let maintenanceFailed=false;
    for(let i=0;i<statements.length;i+=80){try{await env.DB.batch(statements.slice(i,i+80));}catch(e){maintenanceFailed=true;logErr('web offer quality batch',e);break;}}
    if(maintenanceFailed)return;
    for(const key of [...touched].slice(0,160)){
      const [productKey,country]=key.split('|'); if(productKey&&country)await webIndexUpdateMarketCounts(productKey,country,env);
    }
    await env.DB.prepare(`INSERT OR REPLACE INTO web_index_maintenance(migration_key,completed_at) VALUES(?,?)`).bind(WEB_INDEX_QUALITY_MIGRATION,now).run();
  }catch(e){logErr('web offer quality maintenance',e);}
}
async function ensureWebDiscoverySchema(env) {
  if (WEB_DISCOVERY_SCHEMA_READY) return true;
  if (!env || !env.DB) return false;
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS web_discovery_cache (
    cache_key TEXT PRIMARY KEY,
    query TEXT NOT NULL,
    country TEXT NOT NULL,
    corrected_query TEXT NOT NULL DEFAULT '',
    results_json TEXT NOT NULL DEFAULT '[]',
    created_at INTEGER NOT NULL,
    expires_at INTEGER NOT NULL
  )`).run();

  // Durable FindAI shopping index. Product identity is global; offers and prices are
  // market-specific so an Australian A$ offer is never silently reused as a US price.
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS web_index_products (
    product_key TEXT PRIMARY KEY,
    canonical_query TEXT NOT NULL,
    family_signature TEXT NOT NULL,
    first_seen_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
  )`).run();
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS findai_scan_products (
    scan_product_key TEXT PRIMARY KEY,
    web_product_key TEXT NOT NULL DEFAULT '',
    identity_signature TEXT NOT NULL DEFAULT '',
    canonical_query TEXT NOT NULL DEFAULT '',
    brand TEXT NOT NULL DEFAULT '',
    product_line TEXT NOT NULL DEFAULT '',
    model TEXT NOT NULL DEFAULT '',
    variant TEXT NOT NULL DEFAULT '',
    size TEXT NOT NULL DEFAULT '',
    barcode TEXT NOT NULL DEFAULT '',
    identity_json TEXT NOT NULL DEFAULT '{}',
    evidence_json TEXT NOT NULL DEFAULT '{}',
    confidence REAL NOT NULL DEFAULT 0,
    first_seen_at INTEGER NOT NULL,
    last_seen_at INTEGER NOT NULL,
    scan_count INTEGER NOT NULL DEFAULT 1,
    last_market_country TEXT NOT NULL DEFAULT ''
  )`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_findai_scan_identity ON findai_scan_products(identity_signature)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_findai_scan_barcode ON findai_scan_products(barcode)`).run();
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS findai_scan_observations (
    image_hash TEXT PRIMARY KEY,
    scan_product_key TEXT NOT NULL,
    market_country TEXT NOT NULL DEFAULT '',
    confidence REAL NOT NULL DEFAULT 0,
    observed_at INTEGER NOT NULL
  )`).run();

  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS web_index_aliases (
    alias_key TEXT NOT NULL,
    market_country TEXT NOT NULL,
    product_key TEXT NOT NULL,
    alias_query TEXT NOT NULL DEFAULT '',
    first_seen_at INTEGER NOT NULL,
    last_seen_at INTEGER NOT NULL,
    PRIMARY KEY(alias_key, market_country)
  )`).run();
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS web_index_markets (
    product_key TEXT NOT NULL,
    market_country TEXT NOT NULL,
    first_seen_at INTEGER NOT NULL,
    last_seen_at INTEGER NOT NULL,
    last_search_at INTEGER NOT NULL DEFAULT 0,
    search_count INTEGER NOT NULL DEFAULT 0,
    last_discovery_at INTEGER NOT NULL DEFAULT 0,
    last_discovery_status TEXT NOT NULL DEFAULT '',
    last_refresh_at INTEGER NOT NULL DEFAULT 0,
    known_offer_count INTEGER NOT NULL DEFAULT 0,
    known_retailer_count INTEGER NOT NULL DEFAULT 0,
    last_authority_check_at INTEGER NOT NULL DEFAULT 0,
    authority_coverage_status TEXT NOT NULL DEFAULT '',
    authority_missing_hosts TEXT NOT NULL DEFAULT '',
    PRIMARY KEY(product_key, market_country)
  )`).run();
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS web_index_variants (
    variant_key TEXT PRIMARY KEY,
    product_key TEXT NOT NULL,
    variant_signature TEXT NOT NULL DEFAULT 'base',
    variant_label TEXT NOT NULL DEFAULT 'Default',
    attributes_json TEXT NOT NULL DEFAULT '{}',
    first_seen_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
  )`).run();

  // v65: a non-destructive canonical identity layer. The old web_index_products row stays
  // as the broad search family so existing Search/Deals behaviour is stable. Exact models
  // and price-changing variants live here and offers map to the most specific entity we can
  // prove. This is the foundation later used by Price Tracker and SEO product pages.
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS web_index_entities (
    entity_key TEXT PRIMARY KEY,
    family_product_key TEXT NOT NULL,
    parent_entity_key TEXT NOT NULL DEFAULT '',
    entity_type TEXT NOT NULL DEFAULT 'family',
    canonical_name TEXT NOT NULL,
    brand TEXT NOT NULL DEFAULT '',
    model TEXT NOT NULL DEFAULT '',
    variant_signature TEXT NOT NULL DEFAULT 'base',
    variant_label TEXT NOT NULL DEFAULT 'Default',
    identifiers_json TEXT NOT NULL DEFAULT '{}',
    attributes_json TEXT NOT NULL DEFAULT '{}',
    identity_confidence REAL NOT NULL DEFAULT 0.50,
    seo_slug TEXT NOT NULL DEFAULT '',
    first_seen_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
  )`).run();
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS web_index_offer_entities (
    offer_key TEXT PRIMARY KEY,
    entity_key TEXT NOT NULL,
    confidence REAL NOT NULL DEFAULT 0.50,
    match_basis TEXT NOT NULL DEFAULT 'family',
    mapped_at INTEGER NOT NULL
  )`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_entities_family ON web_index_entities(family_product_key,entity_type,identity_confidence DESC)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_entities_slug ON web_index_entities(seo_slug)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_offer_entities_entity ON web_index_offer_entities(entity_key)`).run();

  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS web_index_offers (
    offer_key TEXT PRIMARY KEY,
    product_key TEXT NOT NULL,
    variant_key TEXT NOT NULL DEFAULT '',
    market_country TEXT NOT NULL,
    market_source TEXT NOT NULL DEFAULT '',
    market_confidence REAL NOT NULL DEFAULT 0.75,
    retailer_host TEXT NOT NULL,
    retailer_name TEXT NOT NULL,
    title TEXT NOT NULL,
    price REAL NOT NULL,
    currency TEXT NOT NULL,
    sku TEXT NOT NULL DEFAULT '',
    mpn TEXT NOT NULL DEFAULT '',
    gtin TEXT NOT NULL DEFAULT '',
    image_url TEXT NOT NULL DEFAULT '',
    image_status TEXT NOT NULL DEFAULT 'unknown',
    image_checked_at INTEGER NOT NULL DEFAULT 0,
    product_url TEXT NOT NULL,
    shipping_cost REAL,
    shipping_text TEXT NOT NULL DEFAULT '',
    availability TEXT NOT NULL DEFAULT 'unknown',
    condition_text TEXT NOT NULL DEFAULT '',
    source TEXT NOT NULL DEFAULT 'web',
    confidence REAL NOT NULL DEFAULT 0.80,
    first_seen_at INTEGER NOT NULL,
    last_seen_at INTEGER NOT NULL,
    last_checked_at INTEGER NOT NULL,
    last_refresh_attempt_at INTEGER NOT NULL DEFAULT 0,
    last_price_change_at INTEGER NOT NULL,
    refresh_failures INTEGER NOT NULL DEFAULT 0,
    active INTEGER NOT NULL DEFAULT 1
  )`).run();
  // Existing D1 databases are upgraded in-place. D1 throws if a column already exists,
  // so each ALTER is intentionally isolated and harmless on later Worker starts.
  for (const ddl of [
    `ALTER TABLE web_index_offers ADD COLUMN variant_key TEXT NOT NULL DEFAULT ''`,
    `ALTER TABLE web_index_offers ADD COLUMN market_source TEXT NOT NULL DEFAULT ''`,
    `ALTER TABLE web_index_offers ADD COLUMN market_confidence REAL NOT NULL DEFAULT 0.75`,
    `ALTER TABLE web_index_offers ADD COLUMN sku TEXT NOT NULL DEFAULT ''`,
    `ALTER TABLE web_index_offers ADD COLUMN mpn TEXT NOT NULL DEFAULT ''`,
    `ALTER TABLE web_index_offers ADD COLUMN gtin TEXT NOT NULL DEFAULT ''`,
    `ALTER TABLE web_index_offers ADD COLUMN image_status TEXT NOT NULL DEFAULT 'unknown'`,
    `ALTER TABLE web_index_offers ADD COLUMN image_checked_at INTEGER NOT NULL DEFAULT 0`,
    `ALTER TABLE web_index_markets ADD COLUMN last_authority_check_at INTEGER NOT NULL DEFAULT 0`,
    `ALTER TABLE web_index_markets ADD COLUMN authority_coverage_status TEXT NOT NULL DEFAULT ''`,
    `ALTER TABLE web_index_markets ADD COLUMN authority_missing_hosts TEXT NOT NULL DEFAULT ''`,
    `ALTER TABLE web_index_authority_retailers ADD COLUMN resolver_version TEXT NOT NULL DEFAULT ''`
  ]) { try { await env.DB.prepare(ddl).run(); } catch (_) {} }
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS web_index_price_history (
    offer_key TEXT NOT NULL,
    observed_at INTEGER NOT NULL,
    price REAL NOT NULL,
    currency TEXT NOT NULL,
    PRIMARY KEY(offer_key, observed_at)
  )`).run();

  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS web_index_retailers (
    retailer_host TEXT PRIMARY KEY,
    canonical_name TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT 'retailer',
    trust_tier INTEGER NOT NULL DEFAULT 55,
    logo_url TEXT NOT NULL DEFAULT '',
    first_seen_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
  )`).run();

  // Self-learning retailer graph. The static registry is only a seed: every verified
  // retailer offer teaches FindAI which domains reliably sell a brand/category in a
  // particular market, so future products can target those stores without code changes.
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS web_index_retailer_profiles (
    retailer_host TEXT NOT NULL,
    market_country TEXT NOT NULL,
    category TEXT NOT NULL DEFAULT '',
    brand TEXT NOT NULL DEFAULT '',
    verified_offer_count INTEGER NOT NULL DEFAULT 0,
    first_seen_at INTEGER NOT NULL,
    last_seen_at INTEGER NOT NULL,
    PRIMARY KEY(retailer_host, market_country, category, brand)
  )`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_retailer_profiles_lookup ON web_index_retailer_profiles(market_country,category,brand,verified_offer_count DESC,last_seen_at DESC)`).run();

  // v51: every credible retailer URL found by Brave becomes durable discovery memory,
  // even when the first retailer-page extraction fails. Brave is the scout; this table
  // lets later searches retry the retailer directly without paying to rediscover it.
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS web_index_discovered_urls (
    lead_key TEXT PRIMARY KEY,
    product_key TEXT NOT NULL,
    market_country TEXT NOT NULL,
    query_text TEXT NOT NULL DEFAULT '',
    retailer_host TEXT NOT NULL,
    retailer_name TEXT NOT NULL DEFAULT '',
    url TEXT NOT NULL,
    result_title TEXT NOT NULL DEFAULT '',
    result_description TEXT NOT NULL DEFAULT '',
    source_kind TEXT NOT NULL DEFAULT 'broad',
    status TEXT NOT NULL DEFAULT 'new',
    confidence REAL NOT NULL DEFAULT 0,
    first_seen_at INTEGER NOT NULL,
    last_seen_at INTEGER NOT NULL,
    last_attempt_at INTEGER NOT NULL DEFAULT 0,
    last_success_at INTEGER NOT NULL DEFAULT 0,
    failure_count INTEGER NOT NULL DEFAULT 0,
    next_retry_at INTEGER NOT NULL DEFAULT 0,
    last_error TEXT NOT NULL DEFAULT '',
    resolver_version TEXT NOT NULL DEFAULT ''
  )`).run();
  await env.DB.prepare(`CREATE UNIQUE INDEX IF NOT EXISTS idx_web_index_discovered_url_unique ON web_index_discovered_urls(product_key,market_country,url)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_discovered_retry ON web_index_discovered_urls(product_key,market_country,status,next_retry_at,confidence DESC)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_discovered_host ON web_index_discovered_urls(product_key,market_country,retailer_host,status,next_retry_at)`).run();

  // Per-product, per-market, per-retailer discovery state. Authority coverage must be
  // deterministic: a failed JB Hi-Fi lookup should not suppress Apple, Harvey Norman or
  // any other retailer, and a successful retailer should not be rediscovered on every search.
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS web_index_authority_retailers (
    product_key TEXT NOT NULL,
    market_country TEXT NOT NULL,
    retailer_host TEXT NOT NULL,
    retailer_name TEXT NOT NULL DEFAULT '',
    last_attempt_at INTEGER NOT NULL DEFAULT 0,
    last_success_at INTEGER NOT NULL DEFAULT 0,
    last_status TEXT NOT NULL DEFAULT '',
    failure_count INTEGER NOT NULL DEFAULT 0,
    product_url TEXT NOT NULL DEFAULT '',
    resolver_version TEXT NOT NULL DEFAULT '',
    updated_at INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY(product_key, market_country, retailer_host)
  )`).run();


  // v40: authority resolution is variant-aware. A retailer resolved for an LG C6 65"
  // must not put an LG C6 48" lookup on cooldown. New reads/writes use this table;
  // the family-level table above remains for backwards compatibility with older data.
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS web_index_authority_variants (
    product_key TEXT NOT NULL,
    market_country TEXT NOT NULL,
    variant_signature TEXT NOT NULL DEFAULT 'base',
    retailer_host TEXT NOT NULL,
    retailer_name TEXT NOT NULL DEFAULT '',
    last_attempt_at INTEGER NOT NULL DEFAULT 0,
    last_success_at INTEGER NOT NULL DEFAULT 0,
    last_status TEXT NOT NULL DEFAULT '',
    failure_count INTEGER NOT NULL DEFAULT 0,
    product_url TEXT NOT NULL DEFAULT '',
    resolver_version TEXT NOT NULL DEFAULT '',
    updated_at INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY(product_key, market_country, variant_signature, retailer_host)
  )`).run();

  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_discovery_cache_expires ON web_discovery_cache(expires_at)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_alias_product ON web_index_aliases(product_key,market_country)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_alias_market_seen ON web_index_aliases(market_country,last_seen_at DESC)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_variant_product ON web_index_variants(product_key,variant_signature)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_offer_product_market ON web_index_offers(product_key,market_country,active,last_checked_at)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_offer_variant_market ON web_index_offers(variant_key,market_country,active,last_checked_at)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_offer_host ON web_index_offers(retailer_host,market_country)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_offer_sku ON web_index_offers(retailer_host,market_country,sku)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_offer_mpn ON web_index_offers(retailer_host,market_country,mpn)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_offer_gtin ON web_index_offers(market_country,gtin)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_offer_refresh ON web_index_offers(active,last_checked_at,last_refresh_attempt_at)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_market_search ON web_index_markets(last_search_at,search_count)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_history_offer ON web_index_price_history(offer_key,observed_at)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_retailer_role ON web_index_retailers(role,trust_tier)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_authority_retry ON web_index_authority_retailers(market_country,last_attempt_at,last_status)`).run();
  await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_web_index_authority_variant_retry ON web_index_authority_variants(market_country,variant_signature,last_attempt_at,last_status)`).run();
  // Retire editorial and comparison/aggregator pages learned by older permissive builds.
  // Do NOT blanket-retire a low-confidence search fallback: a verified manufacturer
  // (e.g. LG) may be a perfectly valid product page even when Brave supplied the price.
  try { await env.DB.prepare(`UPDATE web_index_offers SET active=0 WHERE lower(retailer_host) IN ('tomsguide.com','techradar.com','cnet.com','theverge.com','wired.com','engadget.com','tomshardware.com','pcmag.com','forbes.com','businessinsider.com','gizmodo.com','digitaltrends.com','trustedreviews.com','whathifi.com','getprice.com.au') OR lower(product_url) LIKE '%/news/%' OR lower(product_url) LIKE '%/article/%' OR lower(product_url) LIKE '%/articles/%' OR lower(product_url) LIKE '%/review/%' OR lower(product_url) LIKE '%/reviews/%' OR lower(product_url) LIKE '%/guide/%' OR lower(product_url) LIKE '%/guides/%'`).run(); } catch(_) {}
  try { await env.DB.prepare(`UPDATE web_index_retailers SET canonical_name='Getprice',role='aggregator',trust_tier=10,updated_at=? WHERE lower(retailer_host)='getprice.com.au'`).bind(Date.now()).run(); } catch(_) {}
  // v42: search snippets are never a source of truth for a Buy Now price. Keep every legacy
  // snippet-priced row inactive; a direct retailer fetch/browser extraction can re-create a
  // verified offer while the authority tables preserve the retailer relationship.
  try { await env.DB.prepare(`UPDATE web_index_offers SET active=0 WHERE source='web-search'`).run(); } catch(_) {}
  // Backfill market provenance for legacy rows in bounded batches.
  try {
    const marketRows=await env.DB.prepare(`SELECT offer_key,product_url,retailer_host,currency,market_country FROM web_index_offers WHERE market_source='' OR market_source IS NULL LIMIT 120`).all();
    const marketUpdates=[];
    for(const row of (marketRows.results||[])){
      const info=webIndexInferMarket({url:row.product_url,currency:row.currency,retailerHost:row.retailer_host},row.market_country);
      marketUpdates.push(env.DB.prepare(`UPDATE web_index_offers SET market_country=?,market_source=?,market_confidence=? WHERE offer_key=?`).bind(info.country,String(info.source||'').slice(0,40),Number(info.confidence)||0,row.offer_key));
    }
    if(marketUpdates.length)await env.DB.batch(marketUpdates);
  } catch(_) {}

  // Normalize legacy images and unwrap Brave proxies back to original retailer assets.
  try {
    const imageRows=await env.DB.prepare(`SELECT offer_key,image_url,product_url,retailer_host FROM web_index_offers WHERE image_status IN ('','unknown','ok') OR image_url LIKE 'https://imgs.search.brave.com/%' LIMIT 120`).all();
    const imageUpdates=[]; const checkedAt=Date.now();
    for(const row of (imageRows.results||[])){
      const direct=webDiscoveryUnwrapBraveImageUrl(String(row.image_url||''));
      const status=webIndexImageStatus(direct,row.product_url,'');
      imageUpdates.push(env.DB.prepare(`UPDATE web_index_offers SET image_url=?,image_status=?,image_checked_at=? WHERE offer_key=?`).bind(status==='rejected'?'':direct,status,checkedAt,row.offer_key));
    }
    if(imageUpdates.length)await env.DB.batch(imageUpdates);
  } catch(_) {}

  // Clean duplicate retailer-name suffixes appended by search engines.
  try {
    const titleRows=await env.DB.prepare(`SELECT offer_key,title,retailer_name FROM web_index_offers WHERE instr(title,'|')>0 LIMIT 120`).all();
    const titleUpdates=[];
    for(const row of (titleRows.results||[])){
      const clean=webDiscoveryCleanRetailerTitle(row.title,row.retailer_name);
      if(clean && clean!==String(row.title||''))titleUpdates.push(env.DB.prepare(`UPDATE web_index_offers SET title=? WHERE offer_key=?`).bind(clean,row.offer_key));
    }
    if(titleUpdates.length)await env.DB.batch(titleUpdates);
  } catch(_) {}

  // Merge legacy size-specific product families (e.g. "LG C6 48") into the canonical family.
  try {
    const legacyProducts=await env.DB.prepare(`SELECT p.product_key,p.canonical_query,p.family_signature FROM web_index_products p WHERE NOT EXISTS (SELECT 1 FROM web_index_offers o WHERE o.product_key=p.product_key) LIMIT 80`).all();
    for(const row of (legacyProducts.results||[])){
      const canonical=webIndexCanonicalFamilyQuery(row.canonical_query);
      const target=webIndexProductKey(canonical);
      if(target && target!==String(row.product_key||'')){
        await webIndexMergeProductKeys(String(row.product_key||''),target,canonical,webIndexFamilySignature(canonical),env);
      }
    }
  } catch(_) {}
  // Gradually attach legacy family-only offers to explicit variants. This is bounded so
  // deployment remains cheap even after the catalogue becomes large; fresh searches and
  // refreshes also fill variant_key, so the migration naturally converges.
  try {
    const legacy=await env.DB.prepare(`SELECT o.offer_key,o.product_key,o.title,p.canonical_query FROM web_index_offers o LEFT JOIN web_index_products p ON p.product_key=o.product_key WHERE o.variant_key='' OR o.variant_key IS NULL LIMIT 250`).all();
    const now=Date.now();
    for(const row of (legacy.results||[])){
      const d=webIndexVariantDescriptor(row.title,row.canonical_query||row.title);
      const vk=webIndexVariantKey(row.product_key,d.signature);
      await env.DB.prepare(`INSERT INTO web_index_variants(variant_key,product_key,variant_signature,variant_label,attributes_json,first_seen_at,updated_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(variant_key) DO UPDATE SET variant_label=excluded.variant_label,attributes_json=excluded.attributes_json,updated_at=excluded.updated_at`)
        .bind(vk,row.product_key,d.signature,d.label,JSON.stringify(d.attributes),now,now).run();
      await env.DB.prepare(`UPDATE web_index_offers SET variant_key=? WHERE offer_key=? AND (variant_key='' OR variant_key IS NULL)`).bind(vk,row.offer_key).run();
    }
  } catch(_) {}
  // Run the current offer-quality migration after the bounded legacy variant backfill so peer-price
  // quarantine compares like-for-like variants wherever possible.
  await webIndexRunOfferQualityMaintenance(env);
  WEB_DISCOVERY_SCHEMA_READY = true;
  return true;
}
async function webDiscoveryReadCache(query, country, env) {
  if (!env || !env.DB) return null;
  try {
    await ensureWebDiscoverySchema(env);
    let row = await env.DB.prepare(`SELECT corrected_query, results_json, created_at, expires_at FROM web_discovery_cache WHERE cache_key=? AND expires_at>? LIMIT 1`)
      .bind(webDiscoveryCacheKey(query,country), Date.now()).first();
    let legacy = false;
    if (!row) {
      const legacyKey = `v2|${webDiscoveryCountry(country)}|${String(query || '').toLowerCase().replace(/\s+/g,' ').trim()}`;
      row = await env.DB.prepare(`SELECT corrected_query, results_json, created_at, expires_at FROM web_discovery_cache WHERE cache_key=? AND expires_at>? LIMIT 1`)
        .bind(legacyKey, Date.now()).first();
      legacy = !!row;
    }
    if (!row) return null;
    const items = JSON.parse(String(row.results_json || '[]'));
    return { items: Array.isArray(items) ? items : [], correctedQuery: String(row.corrected_query || query), cached: true, createdAt: Number(row.created_at)||0, legacy };
  } catch (_) { return null; }
}
async function webDiscoveryWriteCache(query, country, correctedQuery, items, env, ttlMs) {
  if (!env || !env.DB) return;
  try {
    await ensureWebDiscoverySchema(env);
    const now = Date.now();
    await env.DB.prepare(`INSERT INTO web_discovery_cache(cache_key,query,country,corrected_query,results_json,created_at,expires_at)
      VALUES(?,?,?,?,?,?,?) ON CONFLICT(cache_key) DO UPDATE SET query=excluded.query,country=excluded.country,corrected_query=excluded.corrected_query,results_json=excluded.results_json,created_at=excluded.created_at,expires_at=excluded.expires_at`)
      .bind(webDiscoveryCacheKey(query,country), String(query||'').slice(0,220), webDiscoveryCountry(country), String(correctedQuery||query).slice(0,220), JSON.stringify(Array.isArray(items)?items:[]), now, now + ttlMs).run();
  } catch (_) {}
}
function webDiscoverySafeUrl(value) {
  try {
    const u = new URL(String(value || ''));
    if (!/^https?:$/.test(u.protocol) || u.username || u.password) return null;
    const h = u.hostname.toLowerCase();
    if (!h || h === 'localhost' || h.endsWith('.local') || h.endsWith('.internal')) return null;
    if (/^(127\.|10\.|0\.|169\.254\.|192\.168\.)/.test(h)) return null;
    const m = h.match(/^172\.(\d+)\./); if (m && Number(m[1]) >= 16 && Number(m[1]) <= 31) return null;
    if (h === '::1' || h.startsWith('fc') || h.startsWith('fd')) return null;
    u.hash = '';
    return u.toString();
  } catch (_) { return null; }
}
function webDiscoveryExcludedHost(hostname) {
  const h = String(hostname || '').toLowerCase().replace(/^www\./,'');
  return [
    'ebay.','amazon.','aliexpress.','stockx.','etsy.','discogs.','findai.ai',
    'google.','bing.com','brave.com','yahoo.','duckduckgo.com','wikipedia.org','reddit.com',
    'youtube.com','youtu.be','facebook.com','instagram.com','tiktok.com','pinterest.com','x.com','twitter.com'
  ].some(x => h === x.replace(/\.$/,'') || h.includes(x));
}
function webDiscoveryHostName(url) {
  try { return new URL(url).hostname.toLowerCase().replace(/^www\./,''); } catch (_) { return ''; }
}

// ── Retailer identity + authority registry ──────────────────────────────────
// FindAI does not need a hand-written entry for every store on earth: unknown stores
// still work and their own site metadata supplies a logo/name. This registry gives the
// major global manufacturers, retailers and category specialists a stable canonical
