  const alias=webIndexAliasKey(query); if(!alias)return;
  const c=webDiscoveryCountry(country);
  await env.DB.prepare(`INSERT INTO web_index_aliases(alias_key,market_country,product_key,alias_query,first_seen_at,last_seen_at)
    VALUES(?,?,?,?,?,?) ON CONFLICT(alias_key,market_country) DO UPDATE SET product_key=excluded.product_key,alias_query=excluded.alias_query,last_seen_at=excluded.last_seen_at`)
