function webIndexSeoSlug(value){
  return String(value||'').toLowerCase().replace(/&/g,' and ').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').replace(/-+/g,'-').slice(0,110);
}
function webIndexIdentityBrand(query,title,item){
  let brand=webIndexIdentifierValue(item&&item.brand||item&&item.manufacturer||'',80);
  if(!brand)brand=String(webDiscoveryQueryBrand(`${query||''} ${title||''}`)||'').trim();
  const t=String(`${query||''} ${title||''}`).toLowerCase();
  if(!brand&&/\biphone\b|\bipad\b|\bairpods?\b|\bapple\s+watch\b/.test(t))brand='Apple';
  else if(!brand&&/\bplaystation\b|\bps\s*5\b|\bps5\b/.test(t))brand='Sony';
  else if(!brand&&/\bxbox\b/.test(t))brand='Microsoft';
  return brand.slice(0,80);
}
function webIndexIdentitySpecificModel(query,title){
  const q=webIndexCollapseRepeatedTokens(webIndexCanonicalDisplayQuery(query));
  const t=webIndexCollapseRepeatedTokens(String(title||'').replace(/\s+/g,' ').trim());
  const hay=`${q} ${t}`;
  let m;
  // High-volume families where a generation/model is expressed in normal language rather than an MPN.
  m=hay.match(/\biphone\s+(\d{1,2})(?:\s+(pro\s+max|pro|max|plus|mini|e))?/i);
  if(m)return `iPhone ${m[1]}${m[2]?' '+m[2].replace(/\b\w/g,x=>x.toUpperCase()):''}`;
  m=hay.match(/\b(?:apple\s+)?watch\s+(?:series\s+)?(\d{1,2}|ultra\s*\d?|se\s*\d?)(?:\s+(ultra\s*\d?|se\s*\d?))?/i);
  if(m)return `Apple Watch ${String(m[1]||m[2]||'').replace(/\s+/g,' ').trim()}`;
  m=hay.match(/\bairpods?\s+(pro\s*\d?|max|\d{1,2})(?:\s+(?:with\s+)?(?:anc|active\s+noise\s+cancellation))?/i);
  if(m)return `AirPods ${String(m[1]).replace(/\s+/g,' ').trim()}`;
  // Prefer the retailer title for PS5 because a broad family query ("PlayStation 5")
  // appears before the title in `hay` and would otherwise swallow Slim/Pro/Digital identity.
  const ps5Title=t.match(/\b(?:playstation\s*5|ps5)\s*(pro|slim)?(?:\s+(?:console|edition))?\s*(digital|disc)?/i);
  const ps5Query=q.match(/\b(?:playstation\s*5|ps5)\s*(pro|slim)?(?:\s+(?:console|edition))?\s*(digital|disc)?/i);
  m=(ps5Title&&(ps5Title[1]||ps5Title[2]))?ps5Title:(ps5Query||ps5Title);
  if(m)return ['PlayStation 5',m[1],m[2]].filter(Boolean).join(' ');
  m=hay.match(/\bxbox\s+series\s+([xs])\b/i);if(m)return `Xbox Series ${m[1].toUpperCase()}`;
  // TVs: retain the series/model, leaving screen size to the existing variant layer.
  if(webIndexLikelyTvQuery(hay)){
    const brand=webDiscoveryQueryBrand(hay)||'';
    const tm=hay.match(/\b(?:oled|qned|bravia|neo\s*qled)?\s*([a-z]{1,3}\d{1,3}[a-z0-9-]*)\b/i);
    if(tm&&tm[1]&&!/^(?:4k|8k|1080p)$/i.test(tm[1]))return `${brand?brand.toUpperCase()+' ':''}${tm[1].toUpperCase()}`.trim();
  }
  // Stable style/model codes are strong identity anchors across categories.
  const codes=[...hay.matchAll(/\b([a-z]{1,5}[- ]?\d{3,}[a-z0-9-]*|\d{2,}[a-z]{1,4}[a-z0-9-]*)\b/ig)].map(x=>x[1]).filter(x=>!/^(?:19|20)\d{2}$/.test(x)&&!/^(?:\d+)(?:gb|tb|ml|mm|cm)$/i.test(x));
  if(codes.length){
    const code=codes[0].replace(/\s+/g,'-');
    const base=webIndexCanonicalFamilyQuery(q);
    if(base&&!base.toLowerCase().includes(code.toLowerCase()))return `${base} ${code}`.replace(/\s+/g,' ').trim();
  }
  // An exact shopper query is itself a useful model entity, but broad one-word families are not.
  try{if(findAIQueryScope(q)==='exact'&&q.split(/\s+/).filter(Boolean).length>=2)return q;}catch(_){}
  return '';
}
async function webIndexAttachOfferEntity(offerKey,productKey,query,item,variant,env,seenAt=Date.now()){
  if(!env||!env.DB||!offerKey||!productKey)return null;
  const familyName=webIndexCollapseRepeatedTokens(webIndexCanonicalFamilyQuery(query)||query||item&&item.title||'').slice(0,180);
  if(!familyName)return null;
  const brand=webIndexIdentityBrand(query,item&&item.title,item||{});
  const familyKey='we_'+webIndexDurableHash('family|'+productKey);
  const now=Number(seenAt)||Date.now();
  const familySlug=webIndexSeoSlug(familyName);
  try{await env.DB.prepare(`INSERT INTO web_index_entities(entity_key,family_product_key,parent_entity_key,entity_type,canonical_name,brand,model,variant_signature,variant_label,identifiers_json,attributes_json,identity_confidence,seo_slug,first_seen_at,updated_at)
    VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(entity_key) DO UPDATE SET canonical_name=excluded.canonical_name,brand=CASE WHEN length(excluded.brand)>0 THEN excluded.brand ELSE web_index_entities.brand END,seo_slug=CASE WHEN length(excluded.seo_slug)>0 THEN excluded.seo_slug ELSE web_index_entities.seo_slug END,updated_at=excluded.updated_at`)
    .bind(familyKey,productKey,'','family',familyName,brand,'','base','Default','{}','{}',0.58,familySlug,now,now).run();}catch(_){}

  const gtin=webIndexIdentifierValue(item&&item.gtin,32).replace(/[^0-9]/g,''),mpn=webIndexIdentifierValue(item&&item.mpn,100),sku=webIndexIdentifierValue(item&&item.sku,100);
  const specific=webIndexIdentitySpecificModel(query,item&&item.title||'');
  let leafKey=familyKey,parent=familyKey,basis='family',confidence=0.58,modelName='';
  if(gtin||mpn||specific){
    modelName=webIndexCollapseRepeatedTokens(specific||familyName).slice(0,180);
    const sig=gtin?`gtin:${gtin}`:mpn?`mpn:${String(mpn).toLowerCase()}`:`name:${webIndexAliasKey(modelName)}`;
    const modelKey='we_'+webIndexDurableHash('model|'+productKey+'|'+sig);
    confidence=gtin?0.99:mpn?0.96:0.82;basis=gtin?'gtin':mpn?'mpn':'specific-model';
    const ids=JSON.stringify({gtin:gtin||'',mpn:mpn||'',sku:sku||''});
    try{await env.DB.prepare(`INSERT INTO web_index_entities(entity_key,family_product_key,parent_entity_key,entity_type,canonical_name,brand,model,variant_signature,variant_label,identifiers_json,attributes_json,identity_confidence,seo_slug,first_seen_at,updated_at)
      VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(entity_key) DO UPDATE SET canonical_name=excluded.canonical_name,brand=CASE WHEN length(excluded.brand)>0 THEN excluded.brand ELSE web_index_entities.brand END,model=CASE WHEN length(excluded.model)>0 THEN excluded.model ELSE web_index_entities.model END,identifiers_json=excluded.identifiers_json,identity_confidence=MAX(web_index_entities.identity_confidence,excluded.identity_confidence),seo_slug=excluded.seo_slug,updated_at=excluded.updated_at`)
      .bind(modelKey,productKey,familyKey,'model',modelName,brand,modelName,'base','Default',ids,'{}',confidence,webIndexSeoSlug(modelName),now,now).run();leafKey=modelKey;parent=modelKey;}catch(_){}
  }
  const variantSig=String(variant&&variant.signature||'base'),variantLabel=String(variant&&variant.label||'Default');
  if(variantSig&&variantSig!=='base'){
    const variantKey='we_'+webIndexDurableHash('variant|'+parent+'|'+variantSig),baseName=modelName||familyName,variantName=webIndexCollapseRepeatedTokens(`${baseName} ${variantLabel}`).slice(0,190);
    try{await env.DB.prepare(`INSERT INTO web_index_entities(entity_key,family_product_key,parent_entity_key,entity_type,canonical_name,brand,model,variant_signature,variant_label,identifiers_json,attributes_json,identity_confidence,seo_slug,first_seen_at,updated_at)
      VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(entity_key) DO UPDATE SET canonical_name=excluded.canonical_name,attributes_json=excluded.attributes_json,identity_confidence=MAX(web_index_entities.identity_confidence,excluded.identity_confidence),seo_slug=excluded.seo_slug,updated_at=excluded.updated_at`)
      .bind(variantKey,productKey,parent,'variant',variantName,brand,modelName,variantSig,variantLabel,JSON.stringify({gtin:gtin||'',mpn:mpn||'',sku:sku||''}),JSON.stringify(variant&&variant.attributes||{}),Math.min(0.995,confidence+0.01),webIndexSeoSlug(variantName),now,now).run();leafKey=variantKey;basis=basis==='family'?'variant':basis+'+variant';confidence=Math.min(0.995,confidence+0.01);}catch(_){}
  }
  try{await env.DB.prepare(`INSERT INTO web_index_offer_entities(offer_key,entity_key,confidence,match_basis,mapped_at) VALUES(?,?,?,?,?) ON CONFLICT(offer_key) DO UPDATE SET entity_key=CASE WHEN excluded.confidence>=web_index_offer_entities.confidence THEN excluded.entity_key ELSE web_index_offer_entities.entity_key END,confidence=MAX(web_index_offer_entities.confidence,excluded.confidence),match_basis=CASE WHEN excluded.confidence>=web_index_offer_entities.confidence THEN excluded.match_basis ELSE web_index_offer_entities.match_basis END,mapped_at=excluded.mapped_at`)
    .bind(offerKey,leafKey,confidence,basis,now).run();}catch(_){}
  return {entityKey:leafKey,confidence,basis};
}

