    await env.DB.prepare(`INSERT INTO web_index_retailer_profiles(retailer_host,market_country,category,brand,verified_offer_count,first_seen_at,last_seen_at)
      VALUES(?,?,?,?,1,?,?) ON CONFLICT(retailer_host,market_country,category,brand) DO UPDATE SET verified_offer_count=web_index_retailer_profiles.verified_offer_count+1,last_seen_at=excluded.last_seen_at`)
      .bind(String(host).toLowerCase(),c,category,brand,now,now).run();
