  const role=String((reg&&reg.role)||item&&item.retailerRole||'retailer').slice(0,30);
  const tier=Math.max(1,Math.min(100,Number((reg&&reg.tier)||item&&item.retailerTier||55)||55));
  const logo=webDiscoveryCanonicalRetailerLogo(host) || webDiscoveryImageValue(item&&item.retailerLogo,item&&item.url)||'';
  try { await env.DB.prepare(`INSERT INTO web_index_retailers(retailer_host,canonical_name,role,trust_tier,logo_url,first_seen_at,updated_at)
    VALUES(?,?,?,?,?,?,?) ON CONFLICT(retailer_host) DO UPDATE SET canonical_name=excluded.canonical_name,role=CASE WHEN excluded.trust_tier>=web_index_retailers.trust_tier THEN excluded.role ELSE web_index_retailers.role END,trust_tier=MAX(web_index_retailers.trust_tier,excluded.trust_tier),logo_url=CASE WHEN length(excluded.logo_url)>0 THEN excluded.logo_url ELSE web_index_retailers.logo_url END,updated_at=excluded.updated_at`)
    .bind(host,name,role,tier,logo,now,now).run(); } catch(_) {}
