  if(/\bps4\b/i.test(q)){add(q.replace(/\bps4\b/i,'PlayStation 4'));add(q.replace(/\bps4\b/i,'PlayStation 4 console'));}
  if(/\bairpods?\b/i.test(q)&&!/^apple\b/i.test(q))add('Apple '+q);
  if(/\biphone\b/i.test(q)&&!/^apple\b/i.test(q))add('Apple '+q);
