  for(const f of (facts||[])){if(Number(f.price)>0)allowed.push(Number(f.price));if(Number(f.shipping)>0)allowed.push(Number(f.shipping));}
  const nums=[...String(text||'').matchAll(/(?:A\$|AU\$|US\$|C\$|NZ\$|HK\$|S\$|\$|£|€)\s*([0-9][0-9,]*(?:\.[0-9]+)?)/g)].map(m=>Number(m[1].replace(/,/g,''))).filter(Number.isFinite);
  return nums.every(n=>allowed.some(a=>Math.abs(a-n)<=Math.max(.02,Math.abs(a)*.001)));
