  merchant=await ownedRefreshRobots(env,merchant,options.force===true);
  let robots={};try{robots=JSON.parse(merchant.robots_rules_json||'{}');}catch(_){}
  if(!ownedRobotsAllows('https://'+merchant.domain+'/',robots.rules||[]))throw new Error('robots.txt disallows crawling this merchant');
  let roots=[];try{roots=JSON.parse(merchant.sitemap_urls_json||'[]');}catch(_){}
